import type { Soru } from "../sorular";

export const P11: Soru[] = [
  { id: "p11-001", k: "Bilim", s: "Kuvvetin SI birimi nedir?", d: "Newton", y: ["Joule", "Watt"], a: "Kuvvet newton (N) ile ölçülür. 1 newton, 1 kilogramlık kütleye 1 m/s² ivme kazandıran kuvvettir." },
  { id: "p11-002", k: "Bilim", s: "İvmenin SI birimi hangisidir?", d: "Metre/saniye kare", y: ["Metre/saniye", "Kilogram·metre"], a: "İvme, hızın birim zamandaki değişimidir. Hız m/s olduğu için ivme metre bölü saniye kare (m/s²) ile ölçülür." },
  { id: "p11-003", k: "Bilim", s: "Newton'un birinci hareket yasası hangi adla da bilinir?", d: "Eylemsizlik yasası", y: ["Etki-tepki yasası", "Kütle çekim yasası"], a: "Net kuvvet etki etmedikçe duran cisim durur, hareket eden cisim sabit hızla gitmeye devam eder. Buna eylemsizlik denir." },
  { id: "p11-004", k: "Bilim", s: "Newton'un ikinci yasası hangi formülle ifade edilir?", d: "F = m·a", y: ["E = m·c²", "V = I·R"], a: "Net kuvvet, kütle ile ivmenin çarpımına eşittir. Aynı kuvvet, kütlesi küçük cisme daha büyük ivme kazandırır." },
  { id: "p11-005", k: "Bilim", s: "\"Her etkiye eşit ve zıt bir tepki vardır\" ilkesi Newton'un kaçıncı yasasıdır?", d: "Üçüncü", y: ["Birinci", "İkinci"], a: "Üçüncü yasaya göre iki cisim birbirine eşit büyüklükte ve zıt yönde kuvvet uygular. Bu kuvvetler farklı cisimlere etki eder." },
  { id: "p11-006", k: "Bilim", s: "Hava olmayan bir ortamda çekiç ile kuş tüyü aynı yükseklikten bırakılırsa ne olur?", d: "Aynı anda yere düşerler", y: ["Önce çekiç düşer", "Önce tüy düşer"], a: "Boşlukta bütün cisimler aynı ivmeyle düşer. Astronot David Scott bunu 1971'de Ay'da çekiç ve tüyle gösterdi." },
  { id: "p11-007", k: "Bilim", s: "Yeryüzünde yerçekimi ivmesi yaklaşık kaçtır?", d: "9,8 m/s²", y: ["6,7 m/s²", "12,4 m/s²"], a: "Deniz seviyesinde serbest düşen bir cismin hızı her saniye yaklaşık 9,8 m/s artar. Değer enleme ve yüksekliğe göre biraz değişir." },
  { id: "p11-008", k: "Bilim", s: "Ay yüzeyindeki yerçekimi, Dünya'dakinin yaklaşık ne kadarıdır?", d: "Altıda biri", y: ["Yarısı", "Onda biri"], a: "Ay'da yerçekimi ivmesi yaklaşık 1,6 m/s²'dir. Bu yüzden Dünya'da 60 kg gelen bir kişi Ay'da 10 kg'lık bir yük gibi hissettirir." },
  { id: "p11-009", k: "Bilim", s: "Dünya'dan Ay'a giden bir astronotun kütlesi ne olur?", d: "Değişmez", y: ["Azalır", "Artar"], a: "Kütle madde miktarıdır, yere göre değişmez. Değişen ağırlıktır, çünkü ağırlık kütleye etki eden çekim kuvvetidir." },
  { id: "p11-010", k: "Bilim", s: "Fizikte ağırlık hangi birimle ölçülür?", d: "Newton", y: ["Kilogram", "Litre"], a: "Ağırlık bir kuvvettir, bu yüzden newton ile ölçülür. Günlük dilde kilogram denir ama kilogram kütlenin birimidir." },
  { id: "p11-011", k: "Bilim", s: "Momentum (çizgisel momentum) nasıl hesaplanır?", d: "Kütle × hız", y: ["Kütle × ivme", "Kuvvet × yol"], a: "Momentum p = m·v ile bulunur. Ağır ve hızlı cisimlerin momentumu büyüktür, onları durdurmak daha zordur." },
  { id: "p11-012", k: "Bilim", s: "Sürtünme kuvveti, kayan bir cisme hangi yönde etki eder?", d: "Harekete zıt yönde", y: ["Hareketle aynı yönde", "Her zaman yukarı doğru"], a: "Kinetik sürtünme, yüzeyler arasındaki kaymaya karşı koyar. Bu yüzden kayan cisimler dışarıdan itilmezse yavaşlar." },
  { id: "p11-013", k: "Bilim", s: "Bir roketin havasız uzayda ilerleyebilmesi en iyi hangi yasayla açıklanır?", d: "Etki-tepki yasası", y: ["Hooke yasası", "Ohm yasası"], a: "Roket gazları geriye doğru büyük hızla iter, gazlar da roketi ileri iter. Bunun için itilecek havaya gerek yoktur." },
  { id: "p11-014", k: "Bilim", s: "Otobüs aniden fren yapınca ayaktaki yolcuların öne savrulmasının nedeni nedir?", d: "Eylemsizlik", y: ["Hava basıncı", "Manyetizma"], a: "Yolcunun bedeni hareketini sürdürmeye eğilimlidir. Otobüs yavaşlarken beden hareketine devam ettiği için öne doğru gider." },
  { id: "p11-015", k: "Bilim", s: "Hava direnci yoksa, serbest bırakılan bir taşın 1 saniye sonraki hızı yaklaşık kaçtır?", d: "10 m/s", y: ["5 m/s", "20 m/s"], a: "Yerçekimi ivmesi yaklaşık 9,8 m/s² olduğundan, serbest düşen cismin hızı her saniye yaklaşık 10 m/s artar." },
  { id: "p11-016", k: "Bilim", s: "Havada düşen bir cismin, hava direnci ağırlığına eşitlenince ulaştığı sabit hıza ne denir?", d: "Limit hız", y: ["Kaçış hızı", "Ses hızı"], a: "Hava direnci hızla birlikte artar. Ağırlığa eşit olunca net kuvvet sıfırlanır ve cisim sabit hızla düşmeye devam eder." },
  { id: "p11-017", k: "Bilim", s: "Dünya yüzeyinden kaçış hızı yaklaşık kaçtır?", d: "11,2 km/s", y: ["1,1 km/s", "112 km/s"], a: "Hava direnci hesaba katılmazsa, saniyede yaklaşık 11,2 km hızla fırlatılan bir cisim Dünya'nın çekiminden kurtulabilir." },
  { id: "p11-018", k: "Bilim", s: "Evrensel kütle çekim yasasını kim ortaya koydu?", d: "Isaac Newton", y: ["Galileo Galilei", "Johannes Kepler"], a: "Newton 1687'de yayımlanan Principia adlı eserinde, kütleli her cismin birbirini çektiğini matematiksel olarak açıkladı." },
  { id: "p11-019", k: "Bilim", s: "İki cisim arasındaki mesafe iki katına çıkarsa aralarındaki kütle çekim kuvveti ne olur?", d: "Dörtte birine iner", y: ["Yarıya iner", "Değişmez"], a: "Kütle çekim kuvveti uzaklığın karesiyle ters orantılıdır. Mesafe 2 kat artınca kuvvet 2² = 4 kat azalır." },
  { id: "p11-020", k: "Bilim", s: "Eğik düzlem deneyleriyle düşen cisimlerin düzgün hızlandığını gösteren bilim insanı kimdir?", d: "Galileo Galilei", y: ["Arşimet", "Michael Faraday"], a: "Galileo, topları eğik düzlemden yuvarlayarak düşüşü yavaşlattı ve alınan yolun zamanın karesiyle arttığını ölçtü." },
  { id: "p11-021", k: "Bilim", s: "Gezegenlerin Güneş çevresinde elips yörüngelerde dolandığını gösteren kimdir?", d: "Johannes Kepler", y: ["Nikolaus Kopernik", "Albert Einstein"], a: "Kepler, Tycho Brahe'nin gözlemlerini kullanarak 1609'da gezegen yörüngelerinin çember değil elips olduğunu gösterdi." },
  { id: "p11-022", k: "Bilim", s: "Düzgün çembersel hareket yapan bir cisme etki eden net kuvvet hangi yöndedir?", d: "Çemberin merkezine doğru", y: ["Merkezden dışarı doğru", "Hareketle aynı yönde"], a: "Buna merkezcil kuvvet denir. Cismin hız yönünü sürekli değiştirerek onu çember üzerinde tutar." },
  { id: "p11-023", k: "Bilim", s: "Uluslararası Uzay İstasyonu'nun yüksekliğinde yerçekimi, yeryüzündekinin yaklaşık ne kadarıdır?", d: "Yüzde 90'ı", y: ["Yüzde 10'u", "Neredeyse sıfır"], a: "Astronotlar orada yerçekimi olmadığı için değil, istasyonla birlikte sürekli serbest düşüşte oldukları için süzülür." },
  { id: "p11-024", k: "Bilim", s: "Bir uydunun Dünya'ya çakılmadan yörüngede kalmasını sağlayan nedir?", d: "Yeterince büyük yanal hızı", y: ["Uzayda yerçekimi olmaması", "Motorlarının sürekli çalışması"], a: "Uydu aslında sürekli düşer ama yanlamasına öyle hızlı gider ki yüzey de onun altından kıvrılarak uzaklaşır." },
  { id: "p11-025", k: "Bilim", s: "Kaldıraç, makara gibi basit makineler bize ne kazandırır?", d: "Kuvvetten kazanç", y: ["Enerji kazancı", "İşten kazanç"], a: "Basit makineler işi azaltmaz. Daha az kuvvet uygulanır ama bu kuvvet daha uzun bir yol boyunca uygulanmak zorundadır." },
  { id: "p11-026", k: "Bilim", s: "\"Bana bir dayanak noktası verin, Dünya'yı yerinden oynatayım\" sözü kime atfedilir?", d: "Arşimet", y: ["Pisagor", "Aristoteles"], a: "Söz, Arşimet'in kaldıraç ilkesine dayanır: Kuvvet dayanaktan yeterince uzakta uygulanırsa çok büyük yükler kaldırılabilir." },
  { id: "p11-027", k: "Bilim", s: "Büyüklüğünün yanında yönü de olan fiziksel niceliklere ne denir?", d: "Vektörel", y: ["Skaler", "Boyutsuz"], a: "Kuvvet, hız ve ivme vektörel niceliklerdir. Kütle, sıcaklık ve zaman gibi yalnız büyüklüğü olanlara skaler denir." },
  { id: "p11-028", k: "Bilim", s: "Aşağıdakilerden hangisi skaler bir niceliktir?", d: "Kütle", y: ["Kuvvet", "İvme"], a: "Kütlenin yönü yoktur, yalnız büyüklüğü vardır. Kuvvet ve ivme ise yönüyle birlikte tanımlanır." },
  { id: "p11-029", k: "Bilim", s: "400 metrelik pistte tam bir tur atıp başladığı yere dönen koşucunun yer değiştirmesi nedir?", d: "Sıfır", y: ["400 metre", "800 metre"], a: "Yer değiştirme başlangıç ile bitiş noktası arasındaki farktır. Koşucu 400 m yol aldı ama aynı noktaya döndüğü için yer değiştirmesi sıfırdır." },
  { id: "p11-030", k: "Bilim", s: "72 km/saat hız, kaç metre/saniyeye eşittir?", d: "20 m/s", y: ["7,2 m/s", "72 m/s"], a: "1 km/saat, 1000 m'nin 3600 saniyeye bölümüdür. 72 × 1000 / 3600 = 20 m/s bulunur." },
  { id: "p11-031", k: "Bilim", s: "Düz yolda sabit hızla giden bir araca etki eden net kuvvet nedir?", d: "Sıfır", y: ["Hareket yönünde", "Aracın ağırlığına eşit"], a: "Hız ve yön değişmiyorsa ivme sıfırdır. Motorun itişi ile sürtünme ve hava direnci birbirini dengeler." },
  { id: "p11-032", k: "Bilim", s: "Bir yayın uzamasının uygulanan kuvvetle doğru orantılı olduğunu söyleyen yasa hangisidir?", d: "Hooke yasası", y: ["Boyle yasası", "Ohm yasası"], a: "Robert Hooke 1676'da bu ilişkiyi buldu. Yay esneklik sınırını aşmadığı sürece kuvvet iki katına çıkınca uzama da iki katına çıkar." },
  { id: "p11-033", k: "Bilim", s: "Basit bir sarkacın ipi uzatılırsa salınım periyodu ne olur?", d: "Uzar", y: ["Kısalır", "Değişmez"], a: "Basit sarkacın periyodu ip uzunluğunun kareköküyle orantılıdır. Uzun sarkaçlar daha yavaş salınır." },
  { id: "p11-034", k: "Bilim", s: "Küçük açılarla salınan basit sarkacın ucundaki ağırlık artırılırsa periyodu ne olur?", d: "Değişmez", y: ["Uzar", "Kısalır"], a: "Basit sarkacın periyodu yalnız ip uzunluğuna ve yerçekimi ivmesine bağlıdır, uçtaki kütleye bağlı değildir." },
  { id: "p11-035", k: "Bilim", s: "Foucault sarkacı 1851'de neyi gözle görülür biçimde kanıtladı?", d: "Dünya'nın kendi ekseninde döndüğünü", y: ["Ay'ın Dünya'yı çektiğini", "Işığın dalga olduğunu"], a: "Léon Foucault, Paris'te uzun bir sarkaç astı. Salınım düzlemi saatler içinde yavaşça döndü; bunun nedeni Dünya'nın dönmesiydi." },
  { id: "p11-036", k: "Bilim", s: "Newton'un hareket yasalarını içeren Principia adlı eseri hangi yıl yayımlandı?", d: "1687", y: ["1543", "1905"], a: "Philosophiæ Naturalis Principia Mathematica 1687'de yayımlandı. Hareket yasaları ve evrensel kütle çekimi bu eserde yer alır." },
  { id: "p11-037", k: "Bilim", s: "Kapı kolları neden menteşeden uzak kenara takılır?", d: "Az kuvvetle büyük tork için", y: ["Kapı daha hafif olsun diye", "Sürtünmeyi artırmak için"], a: "Tork, kuvvet ile dönme noktasına uzaklığın çarpımıdır. Kuvvet menteşeden ne kadar uzakta uygulanırsa kapı o kadar kolay açılır." },
  { id: "p11-038", k: "Bilim", s: "Tork (kuvvet momenti) hangi birimle ölçülür?", d: "Newton·metre", y: ["Joule/saniye", "Kilogram/metre"], a: "Tork, kuvvet (N) ile dönme eksenine dik uzaklığın (m) çarpımıdır. Bu yüzden birimi N·m'dir." },
  { id: "p11-039", k: "Bilim", s: "Okyanuslardaki gelgitlerin başlıca nedeni nedir?", d: "Ay'ın kütle çekimi", y: ["Rüzgârlar", "Dünya'nın manyetik alanı"], a: "Ay'ın çekimi Dünya'nın yakın ve uzak yüzlerinde farklıdır, bu fark suyu kabartır. Güneş de etkiler ama etkisi Ay'ınkinin yaklaşık yarısıdır." },
  { id: "p11-040", k: "Bilim", s: "Virajı dönen bir otomobili dönüş yolunda tutan kuvvet nedir?", d: "Lastiklerle yol arasındaki sürtünme", y: ["Motorun çekiş gücü", "Hava direnci"], a: "Virajda gereken merkezcil kuvveti lastiklerle yol arasındaki sürtünme sağlar. Yol buzlanınca sürtünme azalır ve araç dışa kayar." },
  { id: "p11-041", k: "Bilim", s: "Aynı yükseklikten biri yatay atılan, biri serbest bırakılan iki top (hava direnci yok) ne zaman yere çarpar?", d: "Aynı anda", y: ["Önce atılan top", "Önce bırakılan top"], a: "Yatay hız düşey hareketi etkilemez. İki top da aynı düşey ivmeyle düştüğü için düz zeminde aynı anda yere değer." },
  { id: "p11-042", k: "Bilim", s: "Hava direnci olmadan düz zeminde en uzağa atış, yatayla kaç derecelik açıyla yapılır?", d: "45 derece", y: ["30 derece", "60 derece"], a: "İdeal durumda menzil 45 derecede en büyük olur. 30 ve 60 derece ise birbirine eşit ama daha kısa menzil verir." },
  { id: "p11-043", k: "Bilim", s: "Konum-zaman grafiğinde doğrunun eğimi neyi verir?", d: "Hızı", y: ["İvmeyi", "Kütleyi"], a: "Eğim, konumdaki değişimin zamana oranıdır; bu da hızdır. Hız-zaman grafiğinin eğimi ise ivmeyi verir." },
  { id: "p11-044", k: "Bilim", s: "Hız-zaman grafiğinde eğrinin altında kalan alan neyi verir?", d: "Yer değiştirmeyi", y: ["İvmeyi", "Kuvveti"], a: "Hız ile zamanın çarpımı yer değiştirmeyi verir. Grafikte bu çarpım, eğri ile zaman ekseni arasındaki alana karşılık gelir." },
  { id: "p11-045", k: "Bilim", s: "Bir cismin eylemsizliği, yani hareket durumunu değiştirmeye direnci, neye bağlıdır?", d: "Kütlesine", y: ["Hızına", "Hacmine"], a: "Kütlesi büyük cisimleri hızlandırmak ya da durdurmak daha zordur. Eylemsizliğin ölçüsü kütledir." },
  { id: "p11-046", k: "Bilim", s: "Çarpışan iki bilardo topundan oluşan sistemde, dış kuvvet yoksa hangisi korunur?", d: "Toplam momentum", y: ["Her topun hızı", "Her topun yönü"], a: "Dış kuvvet yoksa çarpışmadan önceki toplam momentum, çarpışmadan sonrakine eşittir. Tek tek hızlar değişebilir." },
  { id: "p11-047", k: "Bilim", s: "Otomobillerdeki hava yastıkları yaralanmayı nasıl azaltır?", d: "Durma süresini uzatarak", y: ["Momentumu artırarak", "Aracı hızlandırarak"], a: "Momentum değişimi aynı kalsa da süre uzayınca bedene etki eden ortalama kuvvet küçülür. Bu ilişkiye itme (impuls) denir." },
  { id: "p11-048", k: "Bilim", s: "Cisimler arasındaki kütle çekimini 1798'de laboratuvarda ölçen bilim insanı kimdir?", d: "Henry Cavendish", y: ["Robert Hooke", "Blaise Pascal"], a: "Cavendish burulma terazisiyle kurşun küreler arasındaki çok küçük çekimi ölçtü. Bu deneyden Dünya'nın yoğunluğu ve çekim sabiti G hesaplanabildi." },
  { id: "p11-049", k: "Bilim", s: "Aynı kişi aynı hassas tartıyla tartılırsa nerede biraz daha hafif çıkar?", d: "Ekvatorda", y: ["Kutuplarda", "Fark çıkmaz"], a: "Ekvator, Dünya'nın merkezine daha uzaktır ve dönmenin etkisi orada en büyüktür. Fark küçüktür, yaklaşık binde beş kadar." },
  { id: "p11-050", k: "Bilim", s: "Asansör yukarı doğru hızlanırken içindeki baskül ağırlığınızı nasıl gösterir?", d: "Daha fazla", y: ["Daha az", "Sıfır"], a: "Yukarı ivme için baskülün sizi daha güçlü itmesi gerekir. Asansör aşağı doğru hızlanırken ise baskül daha az gösterir." },
  { id: "p11-051", k: "Bilim", s: "1 newtonluk net kuvvet, 1 kilogramlık bir kütleye hangi ivmeyi kazandırır?", d: "1 m/s²", y: ["9,8 m/s²", "10 m/s²"], a: "Newton birimi tam olarak böyle tanımlanır: 1 N = 1 kg·m/s². Bu, F = m·a ilişkisinden gelir." },
  { id: "p11-052", k: "Bilim", s: "Dünya'da ağırlığı yaklaşık 1 newton olan cisim hangisidir?", d: "100 gramlık bir elma", y: ["1 tonluk bir otomobil", "Bir kum tanesi"], a: "100 gramlık kütlenin ağırlığı 0,1 kg × 9,8 m/s², yani yaklaşık 1 newtondur." },
  { id: "p11-054", k: "Bilim", s: "Kar ayakkabıları insanın karda batmasını nasıl önler?", d: "Ağırlığı geniş alana yayarak", y: ["Ağırlığı azaltarak", "Karı eriterek"], a: "Basınç, kuvvetin alana bölümüdür. Ağırlık aynı kalır ama alan büyüyünce kara uygulanan basınç azalır." },
  { id: "p11-055", k: "Bilim", s: "Basınç nasıl hesaplanır?", d: "Kuvvet bölü alan", y: ["Kuvvet çarpı alan", "Kütle bölü hacim"], a: "Basınç, dik kuvvetin uygulandığı yüzeyin alanına bölünmesiyle bulunur. Birimi pascaldır: 1 Pa = 1 N/m²." },
  { id: "p11-056", k: "Bilim", s: "Sıvıya batırılan cisme etki eden kaldırma kuvveti neye eşittir?", d: "Yerini değiştirdiği sıvının ağırlığına", y: ["Cismin kütlesine", "Sıvının toplam ağırlığına"], a: "Bu, Arşimet ilkesidir. Cisim ne kadar sıvıyı kenara iterse, o sıvının ağırlığı kadar yukarı doğru kuvvet görür." },
  { id: "p11-057", k: "Bilim", s: "Tonlarca çelikten yapılan gemiler neden batmaz?", d: "Ortalama yoğunlukları sudan az", y: ["Çelik sudan hafiftir", "Pervaneler onları yukarı iter"], a: "Gövdenin içi büyük ölçüde havayla doludur. Gemi, kendi ağırlığı kadar su yerinden ettiğinde kaldırma kuvveti ağırlığını dengeler." },
  { id: "p11-058", k: "Bilim", s: "Lut Gölü (Ölü Deniz) suyunda neden çok daha kolay yüzülür?", d: "Tuzlu suyun yoğunluğu yüksek", y: ["Suyu çok sıcak", "Orada yerçekimi zayıf"], a: "Çok tuzlu su, tatlı sudan daha yoğundur. Aynı hacim yer değiştirildiğinde daha büyük kaldırma kuvveti oluşur." },
  { id: "p11-059", k: "Bilim", s: "Hidrolik krikolar hangi ilkeye dayanarak çalışır?", d: "Pascal ilkesi", y: ["Bernoulli ilkesi", "Hooke yasası"], a: "Kapalı bir sıvıya uygulanan basınç her yöne aynen iletilir. Küçük pistona uygulanan kuvvet, büyük pistonda çok daha büyük kuvvete dönüşür." },
  { id: "p11-060", k: "Bilim", s: "Akan bir akışkanda hız arttıkça basıncın düştüğünü söyleyen ilke hangisidir?", d: "Bernoulli ilkesi", y: ["Pascal ilkesi", "Arşimet ilkesi"], a: "Daniel Bernoulli bu ilkeyi 1738'de yayımladı. Daralan bir boruda akışkan hızlanır ve basıncı düşer." },
  { id: "p11-062", k: "Bilim", s: "Deniz seviyesindeki ortalama hava basıncı yaklaşık kaçtır?", d: "101 kilopaskal", y: ["10 kilopaskal", "1000 kilopaskal"], a: "Standart atmosfer basıncı 101.325 pascaldır. Bu, her metrekareye yaklaşık 10 tonluk bir kütlenin ağırlığı kadar kuvvet demektir." },
  { id: "p11-063", k: "Bilim", s: "Bir cismin bütün ağırlığının toplandığı kabul edilen noktaya ne denir?", d: "Ağırlık merkezi", y: ["Destek noktası", "Odak noktası"], a: "Cisim ağırlık merkezinden asılırsa dengede kalır. Ağırlık merkezi alçak olan araçlar daha zor devrilir." },
  { id: "p11-064", k: "Bilim", s: "Enerjinin SI birimi nedir?", d: "Joule", y: ["Newton", "Pascal"], a: "Joule, adını İngiliz fizikçi James Prescott Joule'den alır. 1 joule, 1 newtonluk kuvvetin 1 metre boyunca yaptığı iştir." },
  { id: "p11-065", k: "Bilim", s: "Gücün SI birimi nedir?", d: "Watt", y: ["Joule", "Volt"], a: "Güç, birim zamanda yapılan iş ya da aktarılan enerjidir. 1 watt, saniyede 1 joule demektir." },
  { id: "p11-066", k: "Bilim", s: "Elektrik faturalarındaki kilovatsaat (kWh) neyin birimidir?", d: "Enerjinin", y: ["Gücün", "Akımın"], a: "1 kWh, 1000 wattlık bir cihazın 1 saatte harcadığı enerjidir ve 3,6 milyon joule'e eşittir." },
  { id: "p11-067", k: "Bilim", s: "Kinetik enerji hangi formülle hesaplanır?", d: "½ × kütle × hızın karesi", y: ["Kütle × yerçekimi × yükseklik", "Kütle × hız"], a: "Kinetik enerji hareket enerjisidir; kütle ile hızın karesine bağlıdır. Kütle × g × yükseklik potansiyel enerjiyi, kütle × hız ise momentumu verir." },
  { id: "p11-068", k: "Bilim", s: "Bir aracın hızı iki katına çıkarsa kinetik enerjisi kaç katına çıkar?", d: "4 katına", y: ["2 katına", "8 katına"], a: "Kinetik enerji hızın karesiyle orantılıdır. Bu yüzden yüksek hızda fren mesafesi çok hızlı uzar." },
  { id: "p11-069", k: "Bilim", s: "Yerden yükseğe kaldırılan bir cisimde depolanan enerjiye ne denir?", d: "Yerçekimi potansiyel enerjisi", y: ["Kinetik enerji", "Isı enerjisi"], a: "Bu enerji m·g·h ile hesaplanır. Cisim bırakıldığında potansiyel enerji düşüş sırasında kinetik enerjiye dönüşür." },
  { id: "p11-070", k: "Bilim", s: "Enerjinin korunumu yasası ne söyler?", d: "Enerji yoktan var edilemez, yok edilemez", y: ["Enerji zamanla tükenir", "Enerji yalnız ısıya dönüşebilir"], a: "Kapalı bir sistemde toplam enerji sabittir. Enerji yalnızca bir türden başka bir türe dönüşür." },
  { id: "p11-071", k: "Bilim", s: "Gerilmiş bir yayda ya da çekilmiş bir sapanda hangi enerji depolanır?", d: "Esneklik potansiyel enerjisi", y: ["Nükleer enerji", "Kimyasal enerji"], a: "Biçimi değiştirilen esnek cisimler enerji depolar. Sapan bırakılınca bu enerji taşın kinetik enerjisine dönüşür." },
  { id: "p11-072", k: "Bilim", s: "Güneş panelleri hangi enerji dönüşümünü yapar?", d: "Işık → elektrik", y: ["Isı → kimyasal", "Ses → elektrik"], a: "Güneş pilleri yarı iletken malzemelerde fotovoltaik etkiyle ışığı doğrudan elektrik enerjisine dönüştürür." },
  { id: "p11-073", k: "Bilim", s: "Hidroelektrik santralde elektriğe dönüştürülen enerji öncelikle suyun hangi enerjisidir?", d: "Potansiyel enerjisi", y: ["Kimyasal enerjisi", "Nükleer enerjisi"], a: "Barajda yüksekte biriken suyun potansiyel enerjisi, düşerken kinetik enerjiye, türbinde de elektrik enerjisine dönüşür." },
  { id: "p11-074", k: "Bilim", s: "Ellerinizi birbirine sürtünce ısınmasının nedeni nedir?", d: "Hareket enerjisi ısıya dönüşür", y: ["Ciltten elektrik akar", "Kan basıncı düşer"], a: "Sürtünme, kinetik enerjinin bir kısmını ısı enerjisine dönüştürür. Mağara insanları da ateşi sürtünmeyle yakmıştır." },
  { id: "p11-075", k: "Bilim", s: "Bir pil, çalışırken hangi enerji dönüşümünü yapar?", d: "Kimyasal → elektrik", y: ["Isı → elektrik", "Işık → kimyasal"], a: "Pilin içindeki kimyasal tepkimeler elektronların devrede akmasını sağlar. Pil bittiğinde bu tepkimelerin malzemesi tükenmiştir." },
  { id: "p11-076", k: "Bilim", s: "1 mekanik beygirgücü yaklaşık kaç watt eder?", d: "750 watt", y: ["75 watt", "7500 watt"], a: "James Watt'ın tanımladığı mekanik beygirgücü yaklaşık 746 watttır. Avrupa'da kullanılan metrik beygirgücü ise yaklaşık 735 watttır." },
  { id: "p11-077", k: "Bilim", s: "1 kalori yaklaşık kaç joule'dür?", d: "4,2 joule", y: ["1 joule", "100 joule"], a: "1 kalori, 1 gram suyun sıcaklığını 1 °C artırmak için gereken enerjidir, yaklaşık 4,18 joule. Besinlerdeki \"kalori\" aslında kilokaloridir." },
  { id: "p11-078", k: "Bilim", s: "Dışarıdan enerji almadan sonsuza dek çalışan bir makine neden yapılamaz?", d: "Termodinamik yasaları izin vermez", y: ["Yeterince güçlü mıknatıs yok", "Henüz uygun metal bulunmadı"], a: "Enerji yoktan var edilemez ve her gerçek makinede enerjinin bir kısmı ısı olarak kaybolur. Bu yüzden devridaim makineleri çalışmaz." },
  { id: "p11-079", k: "Bilim", s: "100 joule'lük işi 2 saniyede yapan bir motorun gücü kaç watttır?", d: "50 watt", y: ["200 watt", "102 watt"], a: "Güç, işin süreye bölümüdür: 100 J / 2 s = 50 W." },
  { id: "p11-080", k: "Bilim", s: "Sürtünmesiz bir lunapark rayında tren en hızlı nerede gider?", d: "En alçak noktada", y: ["En yüksek noktada", "Her yerde aynı hızla"], a: "En alçak noktada potansiyel enerji en azdır. Toplam enerji korunduğu için kinetik enerji, dolayısıyla hız en fazladır." },
  { id: "p11-081", k: "Bilim", s: "Gerçek bir makinenin verimi için hangisi doğrudur?", d: "Her zaman %100'den azdır", y: ["Tam %100 olabilir", "%100'ü aşabilir"], a: "Gerçek makinelerde enerjinin bir kısmı sürtünme ve ısı yoluyla kaybolur. Bu yüzden alınan faydalı enerji verilenden hep azdır." },
  { id: "p11-082", k: "Bilim", s: "İş, fizikte nasıl hesaplanır?", d: "Kuvvet × kuvvet yönündeki yol", y: ["Kütle × hız", "Kuvvet / zaman"], a: "Kuvvet yönünde yer değiştirme yoksa fiziksel anlamda iş yapılmaz. Bu yüzden duvarı itip yerinden oynatamayan kişi iş yapmış sayılmaz." },
  { id: "p11-083", k: "Bilim", s: "Uluslararası Birimler Sistemi'nde (SI) kaç temel birim vardır?", d: "7", y: ["5", "10"], a: "Temel birimler metre, kilogram, saniye, amper, kelvin, mol ve kandeladır. Diğer birimler bunlardan türetilir." },
  { id: "p11-084", k: "Bilim", s: "Aşağıdakilerden hangisi bir SI temel birimidir?", d: "Kilogram", y: ["Newton", "Joule"], a: "Kilogram yedi temel birimden biridir. Newton ve joule ise temel birimlerden türetilmiş birimlerdir." },
  { id: "p11-085", k: "Bilim", s: "Metre bugün neye dayanarak tanımlanır?", d: "Işığın boşlukta aldığı yol", y: ["Paris'teki metal çubuk", "Dünya'nın çevresi"], a: "1983'ten beri metre, ışığın boşlukta 1/299.792.458 saniyede aldığı yol olarak tanımlanır." },
  { id: "p11-086", k: "Bilim", s: "Saniye bugün neye dayanarak tanımlanır?", d: "Sezyum atomunun yaydığı ışınım", y: ["Dünya'nın kendi çevresinde dönüşü", "Bir sarkacın salınımı"], a: "1 saniye, sezyum-133 atomunun belirli bir geçişinde yayılan ışınımın 9.192.631.770 salınımının süresidir. Atom saatleri buna dayanır." },
  { id: "p11-087", k: "Bilim", s: "Kilogram 2019'dan beri neye dayanarak tanımlanıyor?", d: "Planck sabitine", y: ["Paris'teki metal silindire", "1 litre suyun kütlesine"], a: "2019'a kadar kilogram, Fransa'da saklanan bir platin-iridyum silindirin kütlesiydi. Artık değişmeyen bir doğa sabitine bağlandı." },
  { id: "p11-088", k: "Bilim", s: "Birimlerin önündeki \"mega\" öneki kaç katını gösterir?", d: "Milyon", y: ["Bin", "Milyar"], a: "Mega 10⁶, yani bir milyon demektir. Kilo bin, giga ise milyar katını gösterir." },
  { id: "p11-089", k: "Bilim", s: "1 nanometre, metrenin kaçta biridir?", d: "Milyarda biri", y: ["Milyonda biri", "Binde biri"], a: "Nano 10⁻⁹ demektir. Bir insan saçının kalınlığı kabaca 50.000 ile 100.000 nanometre arasındadır." },
  { id: "p11-090", k: "Bilim", s: "\"Mikro\" öneki bir birimin kaçta birini gösterir?", d: "Milyonda birini", y: ["Binde birini", "Yüzde birini"], a: "Mikro 10⁻⁶ demektir. Mili binde biri, santi ise yüzde biri gösterir." },
  { id: "p11-091", k: "Bilim", s: "Basıncın SI birimi nedir?", d: "Pascal", y: ["Newton", "Watt"], a: "Birim, adını Fransız bilim insanı Blaise Pascal'dan alır. 1 pascal, metrekareye 1 newtonluk kuvvet demektir." },
  { id: "p11-092", k: "Bilim", s: "Frekansın SI birimi nedir?", d: "Hertz", y: ["Desibel", "Kelvin"], a: "1 hertz, saniyede bir titreşim ya da tekrar demektir. Birim, elektromanyetik dalgaları deneyle gösteren Heinrich Hertz'in adını taşır." },
  { id: "p11-094", k: "Bilim", s: "Işık şiddetinin SI temel birimi hangisidir?", d: "Kandela", y: ["Lüks", "Lümen"], a: "Kandela, belirli bir yöndeki ışık şiddetini ölçer. Lümen ve lüks ise kandeladan türetilen birimlerdir." },
  { id: "p11-095", k: "Bilim", s: "Madde miktarının SI temel birimi hangisidir?", d: "Mol", y: ["Gram", "Litre"], a: "1 mol, yaklaşık 6,022 × 10²³ tane tanecik içerir. Bu sayıya Avogadro sayısı denir." },
  { id: "p11-096", k: "Bilim", s: "Bir kuvvet bir cismi hareket ettiriyorsa, kuvvetin cisme aktardığı enerjiye fizikte ne denir?", d: "İş", y: ["Güç", "Momentum"], a: "Fizikte iş, kuvvetin enerji aktarmasıdır ve joule ile ölçülür. Güç ise bu aktarımın ne kadar hızlı yapıldığını gösterir." },
  { id: "p11-097", k: "Bilim", s: "120 km'lik yolu 2 saatte alan bir aracın ortalama sürati nedir?", d: "60 km/saat", y: ["240 km/saat", "122 km/saat"], a: "Ortalama sürat, alınan yolun geçen süreye bölümüdür: 120 km / 2 saat = 60 km/saat." },
  { id: "p11-098", k: "Bilim", s: "Isaac Newton hangi ülkenin bilim insanıdır?", d: "İngiltere", y: ["Almanya", "İtalya"], a: "Newton 1643'te İngiltere'de doğdu, Cambridge Üniversitesi'nde çalıştı. Matematik, optik ve mekanikte devrim yarattı." },
  { id: "p11-099", k: "Bilim", s: "Kuvveti ölçmek için kullanılan yaylı alete ne denir?", d: "Dinamometre", y: ["Barometre", "Termometre"], a: "Dinamometrede yay, uygulanan kuvvetle orantılı uzar. Uzama miktarı ölçekte newton cinsinden okunur." },
  { id: "p11-100", k: "Bilim", s: "Sıcaklığın SI temel birimi nedir?", d: "Kelvin", y: ["Celsius", "Fahrenheit"], a: "Kelvin ölçeği mutlak sıfırdan başlar. Bir kelvinlik artış, bir Celsius derecelik artışa eşittir." },
  { id: "p11-101", k: "Bilim", s: "Mutlak sıfır, Celsius ölçeğinde yaklaşık kaç derecedir?", d: "−273 °C", y: ["−173 °C", "−373 °C"], a: "Mutlak sıfır −273,15 °C'dir, yani 0 kelvin. Bu, ulaşılabilecek en düşük sıcaklık sınırıdır." },
  { id: "p11-102", k: "Bilim", s: "Su, deniz seviyesinde Fahrenheit ölçeğinde kaç derecede kaynar?", d: "212 °F", y: ["100 °F", "180 °F"], a: "Fahrenheit ölçeğinde su 32 °F'de donar, 212 °F'de kaynar. Arada 180 derece vardır." },
  { id: "p11-103", k: "Bilim", s: "Celsius ve Fahrenheit ölçekleri hangi sıcaklıkta aynı değeri gösterir?", d: "−40 derece", y: ["0 derece", "100 derece"], a: "−40 °C tam olarak −40 °F'ye eşittir. İki ölçeğin kesiştiği tek nokta budur." },
  { id: "p11-104", k: "Bilim", s: "Everest'in zirvesinde su yaklaşık kaç °C'de kaynar?", d: "70 °C", y: ["100 °C", "120 °C"], a: "Zirvede hava basıncı deniz seviyesindekinin yaklaşık üçte biridir. Basınç düşünce kaynama sıcaklığı da düşer." },
  { id: "p11-105", k: "Bilim", s: "Düdüklü tencere yemeği neden daha çabuk pişirir?", d: "Basınç kaynama noktasını yükseltir", y: ["Suyu daha az ısıtır", "Ateşi büyütür"], a: "Kapalı tencerede basınç artar ve su yaklaşık 120 °C'de kaynar. Daha sıcak su yemeği daha kısa sürede pişirir." },
  { id: "p11-106", k: "Bilim", s: "Güneş'in ısısı boşluğu geçerek Dünya'ya hangi yolla ulaşır?", d: "Işıma", y: ["İletim", "Taşınım"], a: "İletim ve taşınım için madde gerekir. Işıma ise elektromanyetik dalgalarla gerçekleşir ve boşlukta da yayılır." },
  { id: "p11-107", k: "Bilim", s: "Sıcak çaya konan metal kaşığın sapı hangi yolla ısınır?", d: "İletim", y: ["Işıma", "Taşınım"], a: "Isınan metal atomları titreşimlerini komşularına aktarır. Metallerde serbest elektronlar bu aktarımı çok hızlandırır." },
  { id: "p11-108", k: "Bilim", s: "Kaloriferin ısıttığı havanın yükselip odayı dolaşmasına ne denir?", d: "Taşınım (konveksiyon)", y: ["İletim", "Yansıma"], a: "Isınan hava genleşir, yoğunluğu azalır ve yükselir. Yerine soğuk hava gelir ve oda içinde bir akım oluşur." },
  { id: "p11-109", k: "Bilim", s: "Termosun çift cidarı arasındaki havası alınmış boşluk neyi azaltır?", d: "İletim ve taşınımla ısı kaybını", y: ["Sıvının buharlaşmasını", "Işığın içeri girmesini"], a: "Boşlukta ısıyı iletecek ya da taşıyacak madde yoktur. Parlak yüzeyler de ışımayla kaybı azaltır." },
  { id: "p11-110", k: "Bilim", s: "Isı, yani aktarılan ısı enerjisi, SI'da hangi birimle ölçülür?", d: "Joule", y: ["Kelvin", "Derece"], a: "Isı bir enerji aktarımıdır, bu yüzden joule ile ölçülür. Kelvin ve derece ise sıcaklık birimleridir." },
  { id: "p11-111", k: "Bilim", s: "Isı kendiliğinden hangi yönde akar?", d: "Sıcak cisimden soğuk cisme", y: ["Soğuk cisimden sıcak cisme", "Büyük cisimden küçük cisme"], a: "Termodinamiğin ikinci yasasına göre ısı kendiliğinden sıcaktan soğuğa akar. Tersi için buzdolabındaki gibi dışarıdan iş gerekir." },
  { id: "p11-112", k: "Bilim", s: "Yalıtılmış bir sistemin entropisi zamanla nasıl değişir?", d: "Artar ya da sabit kalır", y: ["Sürekli azalır", "Kendiliğinden sıfırlanır"], a: "Termodinamiğin ikinci yasasına göre yalıtılmış bir sistemin entropisi azalmaz. Düzensizlik genelde artar." },
  { id: "p11-113", k: "Bilim", s: "Denizler yazın karalardan neden daha yavaş ısınır?", d: "Suyun öz ısısı yüksektir", y: ["Su ışığı hiç soğurmaz", "Deniz suyu tuzludur"], a: "Suyun sıcaklığını artırmak için kara ve kayalara göre çok daha fazla enerji gerekir. Bu yüzden kıyılarda iklim daha ılımandır." },
  { id: "p11-114", k: "Bilim", s: "Tren rayları ve köprüler arasında neden küçük boşluklar bırakılır?", d: "Isıyla genleşmeye yer açmak için", y: ["Yağmur suyu aksın diye", "Ses yalıtımı için"], a: "Metaller ısınınca genleşir. Boşluk bırakılmazsa sıcak günlerde raylar birbirini iter ve eğilebilir." },
  { id: "p11-115", k: "Bilim", s: "Su en yoğun hâline yaklaşık kaç °C'de ulaşır?", d: "4 °C", y: ["0 °C", "100 °C"], a: "Su 4 °C'nin altına soğurken genleşmeye başlar. Bu yüzden göllerin dibindeki su kışın yaklaşık 4 °C'de kalır." },
  { id: "p11-116", k: "Bilim", s: "Buzun suyun üzerinde yüzmesinin nedeni nedir?", d: "Buz sudan daha az yoğundur", y: ["Buzun içi havayla doludur", "Buz suyu iter"], a: "Su donarken molekülleri açık bir kristal yapı kurar ve hacmi yaklaşık yüzde 9 artar. Bu yüzden göller üstten donar." },
  { id: "p11-117", k: "Bilim", s: "Normal basınçta erimekte olan buz-su karışımının sıcaklığı nasıl değişir?", d: "0 °C'de sabit kalır", y: ["Sürekli artar", "Sürekli azalır"], a: "Erime sırasında verilen ısı, sıcaklığı artırmak yerine buzun yapısını çözmek için kullanılır. Buz bitince sıcaklık yükselmeye başlar." },
  { id: "p11-118", k: "Bilim", s: "Terlemek vücudu nasıl serinletir?", d: "Buharlaşan ter deriden ısı alır", y: ["Ter soğuk salgılanır", "Ter güneş ışığını yansıtır"], a: "Sıvının buharlaşması için enerji gerekir ve bu enerji deriden alınır. Nemli havada ter zor buharlaştığı için serinlemek zorlaşır." },
  { id: "p11-119", k: "Bilim", s: "Bir maddenin sıvı olmadan doğrudan katıdan gaza geçmesine ne denir?", d: "Süblimleşme", y: ["Yoğuşma", "Kırağılaşma"], a: "Kuru buz (katı karbondioksit) normal basınçta erimez, doğrudan gaza dönüşür. Tersi olan gazdan katıya geçişe kırağılaşma denir." },
  { id: "p11-120", k: "Bilim", s: "Buzlu içecek bardağının dış yüzünde biriken su damlaları nereden gelir?", d: "Havadaki su buharından", y: ["Bardağın içinden sızan sudan", "Camın kendisinden"], a: "Havadaki su buharı soğuk yüzeye değince yoğuşur ve damlacıklara dönüşür. Bardak sızdırmıyordur." },
  { id: "p11-121", k: "Bilim", s: "0 °C yaklaşık kaç kelvine eşittir?", d: "273 K", y: ["0 K", "100 K"], a: "Kelvin = Celsius + 273,15 ilişkisi vardır. Buna göre suyun donma noktası yaklaşık 273 K, kaynama noktası yaklaşık 373 K'dir." },
  { id: "p11-122", k: "Bilim", s: "Sıcaklık birimi kelvin, hangi bilim insanının unvanından gelir?", d: "William Thomson", y: ["James Joule", "Anders Celsius"], a: "İskoç fizikçi William Thomson'a Lord Kelvin unvanı verildi. 1848'de mutlak sıcaklık ölçeğini önerdi." },
  { id: "p11-123", k: "Bilim", s: "Mutlak sıfır sıcaklığıyla ilgili hangisi doğrudur?", d: "Yaklaşılabilir ama ulaşılamaz", y: ["Laboratuvarda kolayca ulaşılır", "Uzayın her yeri bu sıcaklıktadır"], a: "Termodinamiğin üçüncü yasasına göre sonlu adımlarla mutlak sıfıra ulaşılamaz. Laboratuvarlarda milyarda bir kelvin düzeyine kadar inildi." },
  { id: "p11-124", k: "Bilim", s: "Güneşli bir günde siyah tişört beyaza göre neden daha çok ısınır?", d: "Işığın çoğunu soğurur", y: ["Işığın çoğunu yansıtır", "Havayı daha çok çeker"], a: "Siyah yüzeyler görünür ışığın büyük kısmını soğurur ve bu enerji ısıya dönüşür. Beyaz yüzeyler ışığın çoğunu yansıtır." },
  { id: "p11-125", k: "Bilim", s: "Kat kat giyinmek bizi neden sıcak tutar?", d: "Katmanlar arasındaki hava iyi yalıtkandır", y: ["Kumaş kendisi ısı üretir", "Katmanlar soğuğu dışarı iter"], a: "Durgun hava ısıyı çok kötü iletir. Giysi katmanları arasında hapsolan hava, vücut ısısının kaçmasını yavaşlatır." },
  { id: "p11-126", k: "Bilim", s: "Aynı odadaki metal ve tahta parçasından metal neden daha soğuk hissedilir?", d: "Metal ısıyı daha iyi iletir", y: ["Metalin sıcaklığı daha düşüktür", "Tahta kendi ısısını üretir"], a: "İkisinin sıcaklığı aynıdır. Metal elimizdeki ısıyı çok daha hızlı çektiği için ona dokununca daha soğuk sanırız." },
  { id: "p11-127", k: "Bilim", s: "Isı makinelerinin ulaşabileceği en yüksek verimi 1824'te ortaya koyan bilim insanı kimdir?", d: "Sadi Carnot", y: ["James Watt", "Blaise Pascal"], a: "Fransız mühendis Sadi Carnot, ideal bir ısı makinesinin verimini yalnız sıcak ve soğuk kaynakların sıcaklıklarının belirlediğini gösterdi." },
  { id: "p11-128", k: "Bilim", s: "Güneşte kalan kapalı sprey kutusu neden tehlikelidir?", d: "Isınan gazın basıncı artar", y: ["Gaz donarak genleşir", "Kutu mıknatıslanır"], a: "Sabit hacimde gazın sıcaklığı arttıkça molekülleri duvarlara daha sık ve sert çarpar. Basınç fazla yükselirse kutu patlayabilir." },
  { id: "p11-129", k: "Bilim", s: "Mikrodalga fırın yiyecekleri esas olarak nasıl ısıtır?", d: "Su moleküllerini hareketlendirerek", y: ["Yiyeceği radyoaktif yaparak", "İçindeki havayı yakarak"], a: "Mikrodalgalar, yiyecekteki su gibi polar moleküllerin dönüp titreşmesine yol açar. Bu hareket ısıya dönüşür; yiyecek radyoaktif olmaz." },
  { id: "p11-130", k: "Bilim", s: "Sıvılı termometreler hangi fiziksel özelliğe dayanarak çalışır?", d: "Sıvının ısınınca genleşmesine", y: ["Sıvının renginin değişmesine", "Sıvının ışık yaymasına"], a: "Isınan alkol ya da cıva genleşip ince borudan yükselir. Yükselme miktarı sıcaklıkla orantılıdır." },
  { id: "p11-131", k: "Bilim", s: "Cıvalı termometreyi geliştiren ve adıyla anılan sıcaklık ölçeğini kuran kişi kimdir?", d: "Daniel Gabriel Fahrenheit", y: ["Anders Celsius", "Robert Boyle"], a: "Fahrenheit 1714'te cıvalı termometreyi geliştirdi, 1724'te de kendi ölçeğini önerdi. Bu ölçek bugün ABD'de yaygın kullanılır." },
  { id: "p11-132", k: "Bilim", s: "Ses boşlukta yayılabilir mi?", d: "Hayır, maddesel ortam gerekir", y: ["Evet, ışıktan da hızlı", "Evet, ama çok yavaş"], a: "Ses, maddedeki taneciklerin titreşimiyle yayılır. Uzay boşluğunda titreşecek tanecik olmadığı için ses iletilmez." },
  { id: "p11-133", k: "Bilim", s: "Oda sıcaklığındaki havada ses yaklaşık hangi hızla yayılır?", d: "Saniyede 340 metre", y: ["Saniyede 34 metre", "Saniyede 3400 metre"], a: "20 °C'deki havada ses hızı yaklaşık 343 m/s'dir. Bu, saatte yaklaşık 1235 km eder." },
  { id: "p11-134", k: "Bilim", s: "Ses hangi ortamda en hızlı yayılır?", d: "Çelik", y: ["Su", "Hava"], a: "Ses katılarda genellikle sıvılardan, sıvılarda da gazlardan hızlıdır. Çelikte saniyede yaklaşık 5000-6000 metreye ulaşır." },
  { id: "p11-135", k: "Bilim", s: "Ses deniz suyunda yaklaşık hangi hızla yayılır?", d: "Saniyede 1500 metre", y: ["Saniyede 340 metre", "Saniyede 15.000 metre"], a: "Ses suda havadakinden yaklaşık 4-5 kat hızlıdır. Denizaltılar ve balinalar bu yüzden sesle çok uzak mesafelerden iletişim kurabilir." },
  { id: "p11-136", k: "Bilim", s: "Şimşeği gördükten 3 saniye sonra gök gürültüsü duyulursa, şimşek yaklaşık ne kadar uzaktadır?", d: "1 kilometre", y: ["100 metre", "10 kilometre"], a: "Işık neredeyse anında ulaşır, ses ise saniyede yaklaşık 340 m gider. 3 saniyede ses yaklaşık 1 km yol alır." },
  { id: "p11-138", k: "Bilim", s: "Ses dalgaları havada ne tür dalgalardır?", d: "Boyuna dalga", y: ["Enine dalga", "Elektromanyetik dalga"], a: "Havadaki ses dalgasında tanecikler dalganın ilerleme yönünde ileri geri titreşir. Sıkışma ve seyrelme bölgeleri oluşur." },
  { id: "p11-139", k: "Bilim", s: "Bir sesin ince ya da kalın duyulmasını belirleyen özellik hangisidir?", d: "Frekans", y: ["Genlik", "Yayılma hızı"], a: "Frekans arttıkça ses incelir, azaldıkça kalınlaşır. Kadın sesleri genelde erkek seslerinden daha yüksek frekanslıdır." },
  { id: "p11-140", k: "Bilim", s: "Bir sesin gürlüğünü (şiddetini) esas olarak hangi özelliği belirler?", d: "Genlik", y: ["Frekans", "Dalga hızı"], a: "Genlik, titreşimin büyüklüğüdür. Genlik arttıkça ses dalgası daha çok enerji taşır ve daha gür duyulur." },
  { id: "p11-141", k: "Bilim", s: "Ses düzeyi hangi birimle ifade edilir?", d: "Desibel", y: ["Hertz", "Lümen"], a: "Desibel logaritmik bir ölçektir. Fısıltı yaklaşık 30 dB, yoğun trafik yaklaşık 80-90 dB civarındadır." },
  { id: "p11-142", k: "Bilim", s: "Sağlıklı genç bir insanın duyabildiği ses frekansı aralığı yaklaşık nedir?", d: "20 Hz - 20.000 Hz", y: ["2 Hz - 200 Hz", "200 Hz - 200.000 Hz"], a: "İnsan kulağı yaklaşık 20 ile 20.000 hertz arasını duyar. Yaş ilerledikçe yüksek frekansları duyma yeteneği azalır." },
  { id: "p11-143", k: "Bilim", s: "İnsanın duyabileceğinden yüksek frekanslı seslere ne ad verilir?", d: "Ultrason", y: ["İnfrases", "Mikrodalga"], a: "20.000 Hz'in üstündeki seslere ultrason denir. Tıpta ultrasonografi bu seslerin dokulardan yansımasını kullanır." },
  { id: "p11-144", k: "Bilim", s: "İnsanın duyabileceğinden düşük frekanslı seslere ne ad verilir?", d: "İnfrases", y: ["Ultrason", "Kızılötesi"], a: "20 Hz'in altındaki seslere infrases denir. Filler ve bazı balinalar bu tür seslerle uzak mesafelerden iletişim kurar." },
  { id: "p11-145", k: "Bilim", s: "Gemilerdeki sonar sistemi hangi fiziksel olaydan yararlanır?", d: "Sesin yansımasından (yankı)", y: ["Işığın kırılmasından", "Manyetik çekimden"], a: "Sonar ses dalgası gönderir ve yansıyıp dönmesine kadar geçen süreyi ölçer. Ses hızı bilindiği için uzaklık hesaplanır." },
  { id: "p11-146", k: "Bilim", s: "Yaklaşan ambulansın sireni neden daha ince, uzaklaşırken daha kalın duyulur?", d: "Doppler etkisi", y: ["Rezonans", "Kırınım"], a: "Kaynak yaklaşırken dalgalar sıkışır ve frekans yükselir, uzaklaşırken dalgalar açılır ve frekans düşer." },
  { id: "p11-147", k: "Bilim", s: "Ses hızını aşan bir uçağın yerde duyulan ani patlama sesine ne denir?", d: "Sonik patlama", y: ["Doppler kayması", "Yankı"], a: "Ses hızından hızlı giden uçak önünde bir şok dalgası oluşturur. Bu dalga yerdeki gözlemciye ulaşınca gök gürültüsü gibi bir ses duyulur." },
  { id: "p11-148", k: "Bilim", s: "Bir uçağın \"Mach 2\" hızla uçması ne anlama gelir?", d: "Ses hızının iki katıyla uçar", y: ["Işık hızının iki katıyla uçar", "Saatte 2000 km ile uçar"], a: "Mach sayısı, hızın o ortamdaki ses hızına oranıdır. Birim, Avusturyalı fizikçi Ernst Mach'ın adını taşır." },
  { id: "p11-149", k: "Bilim", s: "Ses düzeyi 10 desibel artarsa ses şiddeti kaç katına çıkar?", d: "10 katına", y: ["2 katına", "100 katına"], a: "Desibel ölçeği logaritmiktir: Her 10 dB artış, şiddetin 10 katına çıkması demektir. 20 dB artış ise 100 kat eder." },
  { id: "p11-150", k: "Bilim", s: "Bir şarkıcının uygun notayla kristal kadehi titreştirip kırması hangi olaya örnektir?", d: "Rezonans", y: ["Kırılma", "Yoğuşma"], a: "Ses kadehin doğal titreşim frekansına denk gelirse titreşim giderek büyür. Yeterince güçlü olursa kadeh çatlayabilir." },
  { id: "p11-151", k: "Bilim", s: "Gitarın teli parmakla kısaltılınca çıkan ses nasıl değişir?", d: "İncelir", y: ["Kalınlaşır", "Hiç değişmez"], a: "Kısa tel daha hızlı titreşir ve frekansı yükselir. Gerginliği artırmak da sesi inceltir." },
  { id: "p11-152", k: "Bilim", s: "Hava ısındıkça içindeki ses hızı nasıl değişir?", d: "Artar", y: ["Azalır", "Değişmez"], a: "Sıcak havada moleküller daha hızlı hareket eder ve titreşimi daha çabuk aktarır. Her 1 °C artış ses hızını yaklaşık 0,6 m/s yükseltir." },
  { id: "p11-153", k: "Bilim", s: "Aktif gürültü önleyici kulaklıklar hangi ilkeyle çalışır?", d: "Yıkıcı girişim", y: ["Yankı", "Kırılma"], a: "Kulaklık dış sesi mikrofonla algılar ve ters evreli bir ses üretir. İki dalga üst üste binince birbirini büyük ölçüde söndürür." },
  { id: "p11-154", k: "Bilim", s: "Işık boşlukta yaklaşık hangi hızla yayılır?", d: "Saniyede 300.000 km", y: ["Saniyede 30.000 km", "Saniyede 3.000.000 km"], a: "Işığın boşluktaki hızı tam olarak saniyede 299.792.458 metredir. Bu hızla ışık bir saniyede Dünya'nın çevresini yaklaşık 7,5 kez dolanır." },
  { id: "p11-155", k: "Bilim", s: "Güneş'ten çıkan ışık Dünya'ya yaklaşık ne kadar sürede ulaşır?", d: "8 dakikada", y: ["8 saniyede", "8 saatte"], a: "Güneş yaklaşık 150 milyon km uzaktadır. Işık bu yolu yaklaşık 8 dakika 20 saniyede alır." },
  { id: "p11-156", k: "Bilim", s: "Beyaz ışığın prizmada renklere ayrıldığını deneylerle gösteren bilim insanı kimdir?", d: "Isaac Newton", y: ["Thomas Edison", "Galileo Galilei"], a: "Newton 1660'larda prizmayla beyaz ışığı renklere ayırdı, ikinci bir prizmayla da renkleri yeniden birleştirip beyaz ışık elde etti." },
  { id: "p11-157", k: "Bilim", s: "Gökkuşağı nasıl oluşur?", d: "Işık su damlalarında kırılıp yansır", y: ["Bulutlar ışığı boyar", "Işık toz zerrelerinde yanar"], a: "Güneş ışığı yağmur damlasına girerken kırılır, içeride yansır ve çıkarken yeniden kırılır. Her renk biraz farklı açıyla kırıldığı için renkler ayrılır." },
  { id: "p11-158", k: "Bilim", s: "Gökkuşağını görebilmek için Güneş nerede olmalıdır?", d: "Gözlemcinin arkasında", y: ["Gözlemcinin karşısında", "Tam tepede"], a: "Gökkuşağı, Güneş'in tam karşısındaki noktanın çevresinde yaklaşık 42 derecelik bir yay olarak görünür." },
  { id: "p11-159", k: "Bilim", s: "Ana gökkuşağının en dış kenarında hangi renk bulunur?", d: "Kırmızı", y: ["Mor", "Yeşil"], a: "Ana gökkuşağında kırmızı dışta, mor içtedir. Daha soluk olan ikincil gökkuşağında ise sıra terstir." },
  { id: "p11-160", k: "Bilim", s: "Gökyüzünün gündüz mavi görünmesinin nedeni nedir?", d: "Mavi ışığın havada daha çok saçılması", y: ["Okyanusların gökyüzüne yansıması", "Havadaki mavi tozlar"], a: "Hava molekülleri kısa dalga boylu mavi ışığı kırmızıdan çok daha fazla saçar. Buna Rayleigh saçılması denir." },
  { id: "p11-161", k: "Bilim", s: "Gün batımında gökyüzünün kızıl görünmesinin başlıca nedeni nedir?", d: "Işığın atmosferde uzun yol alması", y: ["Güneş'in akşam soğuması", "Güneş'in renginin değişmesi"], a: "Akşam Güneş ışığı atmosferde daha uzun yol alır. Mavi ışığın çoğu yolda saçılıp gider, geriye kırmızı ve turuncu tonlar kalır." },
  { id: "p11-162", k: "Bilim", s: "Görünür ışıkta en uzun dalga boyuna sahip renk hangisidir?", d: "Kırmızı", y: ["Mor", "Mavi"], a: "Görünür ışıkta kırmızının dalga boyu yaklaşık 700 nm, morun ise yaklaşık 400 nm'dir." },
  { id: "p11-163", k: "Bilim", s: "Görünür ışıkta foton başına enerjisi en yüksek renk hangisidir?", d: "Mor", y: ["Kırmızı", "Turuncu"], a: "Fotonun enerjisi frekansla artar. Mor ışık görünür renkler arasında en yüksek frekansa, dolayısıyla en yüksek foton enerjisine sahiptir." },
  { id: "p11-164", k: "Bilim", s: "Beyaz ışık altında bir domatesin kırmızı görünmesinin nedeni nedir?", d: "Kırmızı ışığı yansıtıp diğerlerini soğurur", y: ["Kırmızı ışığı soğurur", "Kendisi kırmızı ışık üretir"], a: "Cisimlerin rengi, yansıttıkları ışığa bağlıdır. Domates kırmızıyı yansıtır, diğer renklerin çoğunu soğurur." },
  { id: "p11-165", k: "Bilim", s: "Ekranlar bütün renkleri hangi üç renk ışığı karıştırarak oluşturur?", d: "Kırmızı, yeşil, mavi", y: ["Kırmızı, sarı, mavi", "Siyah, beyaz, gri"], a: "Işıkta ana renkler kırmızı, yeşil ve mavidir (RGB). Üçü eşit şiddette karışınca beyaz ışık elde edilir." },
  { id: "p11-166", k: "Bilim", s: "Kırmızı ve yeşil ışık eşit şiddette üst üste düşürülürse hangi renk görülür?", d: "Sarı", y: ["Kahverengi", "Mor"], a: "Işıklar toplanarak karışır. Kırmızı ile yeşil ışık sarıyı verir; boyalarda ise sonuç farklıdır, çünkü boyalar ışığı soğurur." },
  { id: "p11-167", k: "Bilim", s: "Elektromanyetik dalgalardan hangisinin dalga boyu en uzundur?", d: "Radyo dalgaları", y: ["X-ışınları", "Görünür ışık"], a: "Radyo dalgalarının boyu metreler, hatta kilometreler olabilir. X-ışınlarınınki ise atom boyutlarına yakındır." },
  { id: "p11-168", k: "Bilim", s: "Elektromanyetik dalgalardan hangisinin enerjisi en yüksektir?", d: "Gama ışınları", y: ["Mikrodalgalar", "Kızılötesi"], a: "Gama ışınları spektrumun en kısa dalga boylu, en yüksek frekanslı ucundadır. Örneğin radyoaktif çekirdeklerden yayılırlar." },
  { id: "p11-169", k: "Bilim", s: "Termal (ısı) kameralar hangi ışınımı algılar?", d: "Kızılötesi", y: ["Morötesi", "Gama ışını"], a: "Sıcak cisimler kızılötesi ışınım yayar. Termal kameralar bu ışınımı algılayıp sıcaklık farklarını görüntüye çevirir." },
  { id: "p11-170", k: "Bilim", s: "Güneş yanığına esas olarak hangi ışınım yol açar?", d: "Morötesi (UV)", y: ["Kızılötesi", "Radyo dalgaları"], a: "Morötesi ışınım deri hücrelerindeki DNA'ya zarar verebilir. Bulutlu havada da UV'nin önemli bir kısmı yere ulaşır." },
  { id: "p11-171", k: "Bilim", s: "X-ışınlarını 1895'te keşfeden bilim insanı kimdir?", d: "Wilhelm Röntgen", y: ["Marie Curie", "Ernest Rutherford"], a: "Wilhelm Conrad Röntgen bu keşifle 1901'de verilen ilk Nobel Fizik Ödülü'nü aldı. Bu yüzden X-ışını filmine röntgen denir." },
  { id: "p11-173", k: "Bilim", s: "Gölgelerin oluşması ışığın hangi özelliğini gösterir?", d: "Doğrusal yayılmasını", y: ["Kırılmasını", "Renklere ayrılmasını"], a: "Işık engelin çevresinden dolanmadan düz bir çizgide ilerler. Bu yüzden opak cismin arkasında ışık almayan bir bölge oluşur." },
  { id: "p11-174", k: "Bilim", s: "Su dolu bardağa konan kalemin kırık görünmesinin nedeni nedir?", d: "Işığın kırılması", y: ["Işığın soğurulması", "Kalemin gerçekten bükülmesi"], a: "Işık sudan havaya geçerken hızı değişir ve yön değiştirir. Göz ışığı düz geldiğini varsaydığı için kalem kırık görünür." },
  { id: "p11-175", k: "Bilim", s: "Fiber optik kablolarda ışığın kablo içinde ilerlemesini sağlayan olay hangisidir?", d: "Tam iç yansıma", y: ["Kırınım", "Soğurma"], a: "Işık kablonun çekirdeğinden dış katmana geniş bir açıyla geldiğinde dışarı çıkamaz ve tamamen içeri yansır. Böylece kilometrelerce taşınır." },
  { id: "p11-176", k: "Bilim", s: "Işığın iki ortam arasında kırılma açılarını ilişkilendiren yasa hangisidir?", d: "Snell yasası", y: ["Ohm yasası", "Coulomb yasası"], a: "Hollandalı Willebrord Snellius'un adını taşıyan yasa, gelme ve kırılma açılarını iki ortamın kırılma indisleriyle ilişkilendirir." },
  { id: "p11-177", k: "Bilim", s: "Suyun kırılma indisi yaklaşık kaçtır?", d: "1,33", y: ["0,75", "3,3"], a: "Kırılma indisi, ışığın boşluktaki hızının o ortamdaki hızına oranıdır. Işık suda boşluktakinin yaklaşık dörtte üçü hızla ilerler." },
  { id: "p11-178", k: "Bilim", s: "Işık havadan suya geçtiğinde hızı nasıl değişir?", d: "Azalır", y: ["Artar", "Değişmez"], a: "Işık yoğun ortamlarda boşluktakinden daha yavaş ilerler. Suda hızı saniyede yaklaşık 225.000 km'ye düşer." },
  { id: "p11-179", k: "Bilim", s: "Işık düz bir aynadan yansıdığında gelme açısı ile yansıma açısı arasındaki ilişki nedir?", d: "Birbirine eşittir", y: ["Yansıma açısı iki katıdır", "Toplamları 180 derecedir"], a: "Yansıma yasasına göre gelen ışın, yansıyan ışın ve yüzeyin normali aynı düzlemdedir. Gelme açısı yansıma açısına eşittir." },
  { id: "p11-180", k: "Bilim", s: "Düz aynanın 2 metre önünde duran kişinin görüntüsü aynanın ne kadar arkasında oluşur?", d: "2 metre", y: ["1 metre", "4 metre"], a: "Düz aynada görüntü, cisimle aynı boyda ve aynaya cisimle aynı uzaklıkta, aynanın arkasında oluşur." },
  { id: "p11-181", k: "Bilim", s: "Kendinizi baştan ayağa görebilmek için düz bir duvar aynası en az ne uzunlukta olmalıdır?", d: "Boyunuzun yarısı", y: ["Boyunuz kadar", "Boyunuzun dörtte biri"], a: "Yansıma yasası gereği boyunuzun yarısı uzunluğunda, doğru yüksekliğe asılmış bir ayna yeter. Bu sonuç aynaya uzaklığınıza bağlı değildir." },
  { id: "p11-182", k: "Bilim", s: "El fenerleri ve araba farlarında ışığı paralel demet hâlinde göndermek için hangi ayna kullanılır?", d: "Çukur ayna", y: ["Tümsek ayna", "Düz ayna"], a: "Ampul çukur aynanın odağına yerleştirilir. Aynadan yansıyan ışınlar paralel bir demet oluşturarak uzağa gider." },
  { id: "p11-183", k: "Bilim", s: "Araçların yan aynalarında geniş görüş alanı için hangi ayna kullanılır?", d: "Tümsek ayna", y: ["Çukur ayna", "Düz ayna"], a: "Tümsek ayna daha geniş bir alanı küçültülmüş olarak gösterir. Bu yüzden bazı aynalarda \"nesneler göründüğünden yakındır\" uyarısı bulunur." },
  { id: "p11-184", k: "Bilim", s: "Büyüteç olarak hangi tür mercek kullanılır?", d: "İnce kenarlı (yakınsak) mercek", y: ["Kalın kenarlı (ıraksak) mercek", "Düz cam"], a: "Cisim yakınsak merceğin odak uzaklığından yakına konursa düz ve büyütülmüş bir görüntü görülür." },
  { id: "p11-185", k: "Bilim", s: "Uzağı net göremeyen miyop bir göz hangi tür merceklerle düzeltilir?", d: "Kalın kenarlı (ıraksak)", y: ["İnce kenarlı (yakınsak)", "Renkli düz cam"], a: "Miyop gözde görüntü retinanın önünde oluşur. Iraksak mercek ışığı biraz dağıtarak görüntüyü retinaya taşır." },
  { id: "p11-186", k: "Bilim", s: "Yakını net göremeyen hipermetrop bir göz hangi tür merceklerle düzeltilir?", d: "İnce kenarlı (yakınsak)", y: ["Kalın kenarlı (ıraksak)", "Renkli düz cam"], a: "Hipermetrop gözde görüntü retinanın arkasında oluşur. Yakınsak mercek ışığı biraz toplayarak görüntüyü retinaya getirir." },
  { id: "p11-187", k: "Bilim", s: "Gözlük camlarının kırma gücü hangi birimle ifade edilir?", d: "Diyoptri", y: ["Lüks", "Desibel"], a: "Diyoptri, metre cinsinden odak uzaklığının tersidir. Örneğin odak uzaklığı 0,5 m olan merceğin gücü 2 diyoptridir." },
  { id: "p11-188", k: "Bilim", s: "Göz merceğinin retina üzerinde oluşturduğu görüntü nasıldır?", d: "Ters ve küçük", y: ["Düz ve büyük", "Düz ve küçük"], a: "Göz, kamera gibi ters bir görüntü oluşturur. Beyin bu görüntüyü yorumlayarak dünyayı düz algılamamızı sağlar." },
  { id: "p11-189", k: "Bilim", s: "İlk çalışan yansıtmalı (aynalı) teleskobu 1668'de kim yaptı?", d: "Isaac Newton", y: ["Galileo Galilei", "Christiaan Huygens"], a: "Merceklerde renk saçılması sorun çıkarıyordu. Newton mercek yerine çukur ayna kullanarak bu sorunu aşan bir teleskop yaptı." },
  { id: "p11-190", k: "Bilim", s: "Sıcak asfaltta uzakta su birikintisi varmış gibi görünen serap neden oluşur?", d: "Işığın sıcak hava katmanlarında kırılması", y: ["Asfaltın buhar çıkarması", "Gözün yorulması"], a: "Yere yakın sıcak hava daha az yoğundur. Gökyüzünden gelen ışık bu katmanlarda bükülür ve yerden geliyormuş gibi görünür." },
  { id: "p11-191", k: "Bilim", s: "Yıldızların geceleri \"göz kırpar\" gibi titrek görünmesinin nedeni nedir?", d: "Atmosferdeki hava hareketleri", y: ["Yıldızların sönüp yanması", "Yıldızların dönmesi"], a: "Işık, sıcaklığı ve yoğunluğu sürekli değişen hava katmanlarından geçerken sürekli farklı biçimde kırılır. Uzaydaki teleskoplar bu titreşimi görmez." },
  { id: "p11-192", k: "Bilim", s: "Polarize güneş gözlükleri en çok neyi azaltır?", d: "Yüzeylerden yansıyan parlamayı", y: ["Kızılötesi ısıyı", "Renklerin sayısını"], a: "Su ya da yol yüzeyinden yansıyan ışık büyük ölçüde yatay polarize olur. Polarize camlar bu titreşimi süzerek parlamayı keser." },
  { id: "p11-193", k: "Bilim", s: "Thomas Young'ın 1800'lerin başındaki çift yarık deneyi ışığın hangi özelliğini gösterdi?", d: "Dalga gibi davrandığını", y: ["Kütlesi olduğunu", "Sonsuz hızla gittiğini"], a: "İki yarıktan geçen ışık, ekranda aydınlık ve karanlık şeritler oluşturdu. Bu girişim deseni ancak dalgalarla açıklanabilir." },
  { id: "p11-194", k: "Bilim", s: "Işığın hızının sonlu olduğunu 1676'da Jüpiter'in uydusu İo'yu gözleyerek gösteren kimdir?", d: "Ole Rømer", y: ["Albert Michelson", "Isaac Newton"], a: "Danimarkalı Rømer, İo tutulmalarının Dünya Jüpiter'den uzaklaşırken geciktiğini fark etti. Bu gecikme ışığın yol almak için zamana ihtiyaç duyduğunu gösterdi." },
  { id: "p11-195", k: "Bilim", s: "İnsan gözü gün ışığında en çok hangi renk ışığa duyarlıdır?", d: "Yeşil-sarı", y: ["Mor", "Koyu kırmızı"], a: "Gündüz görüşünde göz yaklaşık 555 nm dalga boyundaki yeşil-sarı ışığa en duyarlıdır. Mor ve koyu kırmızı ışığa duyarlılık çok daha düşüktür." },
  { id: "p11-196", k: "Bilim", s: "Mikrodalgalar ne tür bir dalgadır?", d: "Elektromanyetik dalga", y: ["Ses dalgası", "Su dalgası"], a: "Mikrodalgalar ışık gibi elektromanyetik dalgalardır ama dalga boyları daha uzundur. Radar, Wi-Fi ve mikrodalga fırınlar bunları kullanır." },
  { id: "p11-197", k: "Bilim", s: "Radyo dalgaları boşlukta hangi hızla yayılır?", d: "Işık hızıyla", y: ["Ses hızıyla", "Işık hızının yarısıyla"], a: "Bütün elektromanyetik dalgalar boşlukta aynı hızla, saniyede yaklaşık 300.000 km ile yayılır. Aralarındaki fark dalga boyudur." },
  { id: "p11-198", k: "Bilim", s: "Lazer ışığını sıradan ampul ışığından ayıran temel özellik nedir?", d: "Tek renkli ve eş fazlı olması", y: ["Daha sıcak olması", "Sesten yavaş gitmesi"], a: "Lazer, uyarılmış ışınım salımıyla üretilir. Dalgaları aynı dalga boyunda ve uyum içinde olduğu için dar bir demet hâlinde uzağa gider." },
  { id: "p11-199", k: "Bilim", s: "Siyah görünen bir yüzey üzerine düşen ışığa ne yapar?", d: "Çoğunu soğurur", y: ["Çoğunu yansıtır", "Renklere ayırır"], a: "Siyah yüzey görünür ışığın neredeyse tamamını soğurur, gözümüze çok az ışık döner. Beyaz yüzey ise bütün renkleri yansıtır." },
  { id: "p11-200", k: "Bilim", s: "Işığın keskin bir kenardan ya da dar bir aralıktan geçerken bükülüp yayılmasına ne denir?", d: "Kırınım", y: ["Yansıma", "Soğurma"], a: "Kırınım bütün dalgaların ortak özelliğidir. Aralık dalga boyuna ne kadar yakınsa bükülme o kadar belirgin olur." },
  { id: "p11-201", k: "Bilim", s: "Prizmada beyaz ışığın renklere ayrılmasının nedeni nedir?", d: "Her renk farklı miktarda kırılır", y: ["Prizma ışığı boyar", "Cam renkleri üretir"], a: "Camın kırılma indisi dalga boyuna göre biraz değişir. Mor ışık en çok, kırmızı ışık en az kırılır; bu olaya dağılma (dispersiyon) denir." },
  { id: "p11-202", k: "Bilim", s: "Elektrik akımının SI birimi nedir?", d: "Amper", y: ["Volt", "Ohm"], a: "Amper SI'nın yedi temel biriminden biridir. Adını Fransız fizikçi André-Marie Ampère'den alır." },
  { id: "p11-203", k: "Bilim", s: "Elektriksel gerilimin (potansiyel farkın) birimi nedir?", d: "Volt", y: ["Amper", "Watt"], a: "Volt, adını ilk pili yapan İtalyan fizikçi Alessandro Volta'dan alır. Gerilim, yükleri devrede hareket ettiren \"itme\" gibi düşünülebilir." },
  { id: "p11-204", k: "Bilim", s: "Elektriksel direncin birimi nedir?", d: "Ohm", y: ["Tesla", "Hertz"], a: "Ohm, Alman fizikçi Georg Simon Ohm'un adını taşır ve Yunanca omega (Ω) harfiyle gösterilir." },
  { id: "p11-205", k: "Bilim", s: "Ohm yasası hangi ilişkiyi ifade eder?", d: "Gerilim = akım × direnç", y: ["Güç = akım × zaman", "Akım = gerilim × direnç"], a: "V = I·R ilişkisine göre aynı gerilimde direnç arttıkça akım azalır. Georg Ohm bu ilişkiyi 1827'de yayımladı." },
  { id: "p11-206", k: "Bilim", s: "12 voltluk bir pile bağlı 4 ohmluk dirençten kaç amper akım geçer?", d: "3 amper", y: ["48 amper", "16 amper"], a: "Ohm yasasına göre akım, gerilimin dirence bölümüdür: 12 V / 4 Ω = 3 A." },
  { id: "p11-207", k: "Bilim", s: "230 voltluk prizden 10 amper çeken bir ısıtıcının gücü kaç watttır?", d: "2300 watt", y: ["23 watt", "240 watt"], a: "Elektriksel güç gerilim ile akımın çarpımıdır: 230 V × 10 A = 2300 W." },
  { id: "p11-208", k: "Bilim", s: "Türkiye'de evlerdeki şebeke elektriğinin frekansı kaç hertzdir?", d: "50 Hz", y: ["60 Hz", "100 Hz"], a: "Türkiye ve Avrupa'da alternatif akım saniyede 50 tam döngü yapar. ABD gibi bazı ülkelerde frekans 60 Hz'dir." },
  { id: "p11-209", k: "Bilim", s: "Türkiye'de evlerdeki prizlerin nominal gerilimi yaklaşık kaç volttur?", d: "230 volt", y: ["12 volt", "1000 volt"], a: "Türkiye'de şebeke gerilimi Avrupa standardına uygun olarak 230 volttur. Eskiden 220 volt olarak anılırdı." },
  { id: "p11-210", k: "Bilim", s: "Pillerin sağladığı akım türü hangisidir?", d: "Doğru akım", y: ["Alternatif akım", "Manyetik akım"], a: "Pilde akım hep aynı yönde akar, buna doğru akım denir. Şebeke elektriği ise sürekli yön değiştiren alternatif akımdır." },
  { id: "p11-211", k: "Bilim", s: "\"Akımlar savaşı\"nda Edison'un doğru akımına karşı alternatif akımı savunan mucit kimdir?", d: "Nikola Tesla", y: ["Alexander Graham Bell", "Guglielmo Marconi"], a: "Tesla'nın alternatif akım sistemlerini George Westinghouse destekledi. Alternatif akım, uzak mesafelere iletimde üstün geldi." },
  { id: "p11-212", k: "Bilim", s: "Oda sıcaklığında elektriği en iyi ileten metal hangisidir?", d: "Gümüş", y: ["Demir", "Kurşun"], a: "Gümüşün iletkenliği bakırdan biraz yüksektir. Ancak bakır çok daha ucuz olduğu için kablolarda bakır kullanılır." },
  { id: "p11-213", k: "Bilim", s: "Ev tesisatındaki elektrik kablolarında en çok hangi metal kullanılır?", d: "Bakır", y: ["Demir", "Kurşun"], a: "Bakır çok iyi bir iletkendir, kolay bükülür ve görece ucuzdur. Kabloların dışındaki plastik kılıf ise yalıtkandır." },
  { id: "p11-214", k: "Bilim", s: "Bilgisayar çiplerinin yapımında en çok kullanılan yarı iletken element hangisidir?", d: "Silisyum", y: ["Bakır", "Altın"], a: "Silisyumun iletkenliği, içine çok az miktarda başka element katılarak denetlenebilir. Transistörler bu özelliğe dayanır." },
  { id: "p11-215", k: "Bilim", s: "Çok düşük sıcaklıklara soğutulunca elektriğe karşı direnci sıfıra inen maddelere ne denir?", d: "Süperiletken", y: ["Yarı iletken", "Yalıtkan"], a: "Süperiletkenliği 1911'de Heike Kamerlingh Onnes cıvada keşfetti. MR cihazlarının güçlü mıknatısları süperiletken bobinler kullanır." },
  { id: "p11-216", k: "Bilim", s: "Seri bağlı ampullerden biri bozulursa diğerlerine ne olur?", d: "Hepsi söner", y: ["Daha parlak yanar", "Hiçbir şey olmaz"], a: "Seri devrede akımın izleyebileceği tek bir yol vardır. Bir ampul bozulunca devre kopar ve akım kesilir." },
  { id: "p11-217", k: "Bilim", s: "Evlerdeki lamba ve prizler neden paralel bağlanır?", d: "Her biri bağımsız çalışsın diye", y: ["Daha az kablo kullanılsın diye", "Akım tek yoldan geçsin diye"], a: "Paralel bağlantıda her cihaz aynı şebeke gerilimini alır. Biri kapatıldığında ya da bozulduğunda diğerleri çalışmaya devam eder." },
  { id: "p11-218", k: "Bilim", s: "Evlerdeki sigortaların görevi nedir?", d: "Aşırı akımda devreyi kesmek", y: ["Gerilimi yükseltmek", "Elektrik depolamak"], a: "Kısa devre ya da aşırı yüklenmede akım tehlikeli düzeye çıkar. Sigorta devreyi keserek kabloların ısınıp yangın çıkarmasını önler." },
  { id: "p11-219", k: "Bilim", s: "Yüksek gerilim hattına konan kuşlar neden çarpılmaz?", d: "İki ayakları arasında gerilim farkı yok", y: ["Tüyleri elektriği yalıtır", "Hattaki akım çok zayıftır"], a: "Kuş tek bir tele dokunduğunda ayakları neredeyse aynı potansiyeldedir, bu yüzden bedeninden önemli akım geçmez. İki tele aynı anda değerse çarpılır." },
  { id: "p11-220", k: "Bilim", s: "Elektrik yükünün SI birimi nedir?", d: "Coulomb", y: ["Amper", "Volt"], a: "1 coulomb, 1 amperlik akımın 1 saniyede taşıdığı yüktür. Birim, Fransız fizikçi Charles-Augustin de Coulomb'un adını taşır." },
  { id: "p11-221", k: "Bilim", s: "Aynı cins elektrik yüklü iki cisim birbirine ne yapar?", d: "Birbirini iter", y: ["Birbirini çeker", "Birbirini etkilemez"], a: "Aynı cins yükler (iki pozitif ya da iki negatif) birbirini iter, zıt yükler ise çeker." },
  { id: "p11-222", k: "Bilim", s: "İki yük arasındaki elektriksel kuvvetin uzaklığın karesiyle azaldığını ifade eden yasa hangisidir?", d: "Coulomb yasası", y: ["Ohm yasası", "Snell yasası"], a: "Coulomb 1785'te burulma terazisiyle bu yasayı ortaya koydu. Kuvvet yüklerin çarpımıyla doğru, uzaklığın karesiyle ters orantılıdır." },
  { id: "p11-223", k: "Bilim", s: "Saça sürtülen bir balonun duvara yapışmasının nedeni nedir?", d: "Sürtünmeyle elektron aktarılması", y: ["Balonun mıknatıslanması", "Balonun içindeki gazın ısınması"], a: "Sürtünme sırasında saçtan balona elektron geçer ve balon negatif yüklenir. Yüklü balon duvardaki yükleri kutuplayarak ona tutunur." },
  { id: "p11-224", k: "Bilim", s: "Yıldırım aynı yere iki kez düşer mi?", d: "Evet, sık sık düşebilir", y: ["Hayır, asla düşmez", "Yalnız 100 yılda bir"], a: "Yüksek ve sivri yapılar yıldırımı tekrar tekrar çeker. New York'taki Empire State binasına yılda ortalama 20-25 kez yıldırım düşer." },
  { id: "p11-226", k: "Bilim", s: "Yıldırım kanalındaki hava yaklaşık kaç °C'ye kadar ısınabilir?", d: "30.000 °C", y: ["300 °C", "3 milyon °C"], a: "Yıldırım, çevresindeki havayı bir anda Güneş yüzeyinden yaklaşık beş kat sıcak hâle getirir. Havanın ani genleşmesi gök gürültüsünü oluşturur." },
  { id: "p11-227", k: "Bilim", s: "Yıldırım düşen bir otomobilin içindekileri asıl ne korur?", d: "Aracın metal gövdesi", y: ["Lastik tekerlekler", "Camlar"], a: "Metal gövde bir Faraday kafesi gibi davranır ve akımı dış yüzeyden toprağa iletir. Birkaç santimlik lastik, yıldırımı durduramaz." },
  { id: "p11-228", k: "Bilim", s: "Sürekli akım veren ilk pili 1800'de yapan bilim insanı kimdir?", d: "Alessandro Volta", y: ["Luigi Galvani", "André-Marie Ampère"], a: "Volta, çinko ve bakır diskleri tuzlu suya batırılmış kartonla üst üste dizdi. Bu \"Volta pili\" ilk sürekli elektrik akımı kaynağıydı." },
  { id: "p11-229", k: "Bilim", s: "Bir pile bağlı metal telde elektronlar hangi yönde hareket eder?", d: "Eksi kutuptan artı kutba", y: ["Artı kutuptan eksi kutba", "Hiç hareket etmez"], a: "Elektronlar negatif yüklü olduğu için artı kutba çekilir. Geleneksel akım yönü ise tarihsel olarak tersi, artıdan eksiye kabul edilir." },
  { id: "p11-230", k: "Bilim", s: "Bir telde elektronların ortalama ilerleme (sürüklenme) hızı nasıldır?", d: "Çok yavaş, saniyede milimetre düzeyinde", y: ["Işık hızına eşit", "Ses hızına yakın"], a: "Elektronlar telde çok yavaş ilerler. Lambanın anında yanmasının nedeni, elektrik alanının tel boyunca çok hızlı kurulmasıdır." },
  { id: "p11-231", k: "Bilim", s: "Klasik akkor ampullerde harcanan elektrik enerjisinin çoğu neye dönüşür?", d: "Isıya", y: ["Görünür ışığa", "Sese"], a: "Akkor ampulde enerjinin yalnızca küçük bir kısmı, yaklaşık yüzde 10 ya da daha azı görünür ışık olur. LED'ler aynı ışık için çok daha az enerji harcar." },
  { id: "p11-232", k: "Bilim", s: "Elektrik yükünü depolayan devre elemanına ne denir?", d: "Kondansatör", y: ["Direnç", "Sigorta"], a: "Kondansatör, aralarında yalıtkan bulunan iki iletken levhadan oluşur. Fotoğraf makinesi flaşları gibi ani enerji gereken yerlerde kullanılır." },
  { id: "p11-233", k: "Bilim", s: "Alternatif akımın gerilimini yükseltip alçaltan cihaz hangisidir?", d: "Transformatör", y: ["Kondansatör", "Diyot"], a: "Transformatörde iki bobin aynı demir çekirdeğe sarılıdır. Sarım sayılarının oranı, çıkış geriliminin girişe oranını belirler." },
  { id: "p11-234", k: "Bilim", s: "Elektrik uzak mesafelere neden çok yüksek gerilimle iletilir?", d: "Akım düşer, ısı kaybı azalır", y: ["Elektrik daha hızlı gider", "Kablolar daha hafif olur"], a: "Aynı gücü taşırken gerilim yükselirse akım düşer. Kablolardaki ısı kaybı akımın karesiyle arttığı için kayıp büyük ölçüde azalır." },
  { id: "p11-235", k: "Bilim", s: "Değişen manyetik alanın bir telde akım oluşturduğunu 1831'de keşfeden kimdir?", d: "Michael Faraday", y: ["James Clerk Maxwell", "Georg Ohm"], a: "Faraday'ın keşfettiği elektromanyetik indüksiyon, jeneratörlerin ve transformatörlerin çalışma ilkesidir." },
  { id: "p11-236", k: "Bilim", s: "Bir jeneratör (üreteç) hangi enerji dönüşümünü yapar?", d: "Hareket → elektrik", y: ["Elektrik → hareket", "Işık → elektrik"], a: "Jeneratörde bobin ile mıknatıs birbirine göre döndürülür ve elektromanyetik indüksiyonla akım üretilir." },
  { id: "p11-237", k: "Bilim", s: "Bir elektrik motoru hangi enerji dönüşümünü yapar?", d: "Elektrik → hareket", y: ["Hareket → elektrik", "Isı → elektrik"], a: "Motorda akım taşıyan bobinler manyetik alanda kuvvet etkisinde kalır ve döner. Böylece elektrik enerjisi hareket enerjisine dönüşür." },
  { id: "p11-238", k: "Bilim", s: "1820'de akım taşıyan bir telin pusula iğnesini saptırdığını fark eden bilim insanı kimdir?", d: "Hans Christian Ørsted", y: ["Alessandro Volta", "Benjamin Franklin"], a: "Danimarkalı Ørsted'in bu gözlemi, elektrik ile manyetizmanın birbirine bağlı olduğunu gösteren ilk kanıttı." },
  { id: "p11-239", k: "Bilim", s: "Işığın bir elektromanyetik dalga olduğunu denklemleriyle kuramsal olarak gösteren kimdir?", d: "James Clerk Maxwell", y: ["Isaac Newton", "Niels Bohr"], a: "Maxwell 1860'larda elektrik ve manyetizmayı tek bir kuramda birleştirdi. Denklemlerinden çıkan dalga hızı, ışığın ölçülen hızına eşitti." },
  { id: "p11-240", k: "Bilim", s: "Manyetik alanın (manyetik akı yoğunluğunun) SI birimi nedir?", d: "Tesla", y: ["Weber", "Henry"], a: "Birim, Nikola Tesla'nın adını taşır. Dünya'nın manyetik alanı yüzeyde yaklaşık 25-65 mikrotesla kadardır." },
  { id: "p11-241", k: "Bilim", s: "İki mıknatısın aynı kutupları birbirine yaklaştırılırsa ne olur?", d: "Birbirini iter", y: ["Birbirini çeker", "Birbirine yapışıp kaynaşır"], a: "Mıknatısların zıt kutupları (kuzey-güney) birbirini çeker, aynı kutupları (kuzey-kuzey ya da güney-güney) iter." },
  { id: "p11-242", k: "Bilim", s: "Çubuk bir mıknatıs ortadan ikiye bölünürse ne olur?", d: "Her parça iki kutuplu mıknatıs olur", y: ["Biri kuzey, biri güney kutup olur", "Mıknatıslık tamamen kaybolur"], a: "Tek kutuplu mıknatıs bugüne kadar gözlenmedi. Mıknatıs ne kadar bölünürse bölünsün her parçanın bir kuzey bir güney kutbu olur." },
  { id: "p11-243", k: "Bilim", s: "Pusulanın kuzeyi gösteren ucunu çeken, Dünya'nın coğrafi kuzeyine yakın manyetik kutup fiziksel olarak hangisidir?", d: "Güney manyetik kutup", y: ["Kuzey manyetik kutup", "Kutupsuz bir bölge"], a: "Zıt kutuplar çekiştiği için pusulanın kuzey ucunu çeken kutup aslında bir güney manyetik kutuptur. Adı coğrafi konumundan gelir." },
  { id: "p11-244", k: "Bilim", s: "Aşağıdaki metallerden hangisi mıknatısa güçlü biçimde çekilir?", d: "Demir", y: ["Alüminyum", "Bakır"], a: "Demir, nikel ve kobalt ferromanyetiktir ve mıknatısa güçlü biçimde çekilir. Alüminyum ve bakır kutuları mıknatıs tutmaz." },
  { id: "p11-245", k: "Bilim", s: "Kalıcı bir mıknatıs yeterince yüksek sıcaklığa kadar ısıtılırsa ne olur?", d: "Mıknatıslığını kaybeder", y: ["Daha güçlü mıknatıs olur", "Kutupları yer değiştirir"], a: "Her ferromanyetik maddenin bir Curie sıcaklığı vardır. Bu sıcaklığın üstünde atomların manyetik düzeni bozulur; demirde bu sınır yaklaşık 770 °C'dir." },
  { id: "p11-246", k: "Bilim", s: "Demir çekirdekli bir bobinden akım geçirilerek yapılan mıknatısa ne denir?", d: "Elektromıknatıs", y: ["Doğal mıknatıs", "Süper mıknatıs"], a: "Elektromıknatıs yalnız akım geçerken mıknatıs özelliği gösterir. Hurdalıklardaki vinçler bu sayede demiri tutup bırakabilir." },
  { id: "p11-247", k: "Bilim", s: "Kutup ışıklarını (aurora) oluşturan nedir?", d: "Güneş'ten gelen yüklü parçacıklar", y: ["Buzullardan yansıyan Ay ışığı", "Okyanusta parlayan canlılar"], a: "Güneş'ten gelen yüklü parçacıklar Dünya'nın manyetik alanı boyunca kutuplara yönelir ve atmosferdeki gazları uyararak ışık saçmalarına yol açar." },
  { id: "p11-248", k: "Bilim", s: "Dünya'nın manyetik alanının kaynağı olarak kabul edilen nedir?", d: "Dış çekirdekteki sıvı demirin hareketi", y: ["Yer kabuğundaki mıknatıs kayalar", "Ay'ın çekim kuvveti"], a: "Dış çekirdekteki erimiş demir-nikel karışımının akışı elektrik akımları oluşturur. Bu \"jeodinamo\" manyetik alanı sürekli yeniler." },
  { id: "p11-249", k: "Bilim", s: "MR (manyetik rezonans) cihazları görüntü almak için ne kullanır?", d: "Güçlü manyetik alan ve radyo dalgaları", y: ["X-ışınları", "Ultrason"], a: "MR, vücuttaki hidrojen çekirdeklerinin manyetik alan ve radyo dalgalarına tepkisini ölçer. İyonlaştırıcı ışınım kullanmaz." },
  { id: "p11-250", k: "Bilim", s: "Maglev trenleri raya değmeden nasıl ilerler?", d: "Manyetik kuvvetlerle havada tutularak", y: ["Hava yastığı üzerinde kayarak", "Jet motoruyla uçarak"], a: "Maglev, manyetik kaldırma demektir. Tekerlek-ray sürtünmesi olmadığı için bu trenler saatte 400 km'yi aşan hızlara ulaşabilir." },
  { id: "p11-251", k: "Bilim", s: "Dünya'nın manyetik kutupları jeolojik geçmişte ne yaptı?", d: "Defalarca yer değiştirdi", y: ["Hiç değişmedi", "Tamamen yok oldu"], a: "Volkanik kayalarda donmuş manyetik izler, kutupların geçmişte pek çok kez ters döndüğünü gösterir. Son tam terslenme yaklaşık 780.000 yıl önce oldu." },
  { id: "p11-252", k: "Bilim", s: "Atom çekirdeğini 1911'de altın levha deneyiyle keşfeden bilim insanı kimdir?", d: "Ernest Rutherford", y: ["Niels Bohr", "John Dalton"], a: "Altın levhaya gönderilen alfa parçacıklarının çok azı geri sekti. Rutherford bunu, atomun merkezinde küçük ve yoğun bir çekirdek olmasıyla açıkladı." },
  { id: "p11-253", k: "Bilim", s: "Elektronu 1897'de keşfeden bilim insanı kimdir?", d: "J. J. Thomson", y: ["Ernest Rutherford", "James Chadwick"], a: "Thomson katot ışınlarının atomdan çok daha hafif, negatif yüklü parçacıklardan oluştuğunu gösterdi. Bu, keşfedilen ilk atom altı parçacıktı." },
  { id: "p11-254", k: "Bilim", s: "Nötronu 1932'de keşfeden bilim insanı kimdir?", d: "James Chadwick", y: ["Enrico Fermi", "Max Planck"], a: "İngiliz fizikçi Chadwick, çekirdekte yükü olmayan ve kütlesi protona yakın bir parçacık olduğunu gösterdi. 1935'te Nobel Fizik Ödülü'nü aldı." },
  { id: "p11-255", k: "Bilim", s: "Atom çekirdeğindeki protonların elektrik yükü nedir?", d: "Pozitif", y: ["Negatif", "Yüksüz"], a: "Proton pozitif, elektron negatif yüklüdür ve yüklerinin büyüklüğü eşittir. Nötr bir atomda proton ve elektron sayısı eşittir." },
  { id: "p11-256", k: "Bilim", s: "Protonun kütlesi elektronunkinin yaklaşık kaç katıdır?", d: "Yaklaşık 1800 katı", y: ["Yaklaşık 2 katı", "Yaklaşık 18 katı"], a: "Proton elektrondan yaklaşık 1836 kat ağırdır. Bu yüzden atomun kütlesinin neredeyse tamamı çekirdektedir." },
  { id: "p11-257", k: "Bilim", s: "Bir atomun hacminin büyük bölümünü ne oluşturur?", d: "Boşluk", y: ["Çekirdek", "Protonlar"], a: "Çekirdek, atomdan on binlerce kat küçüktür. Atom bir stadyum kadar büyütülse çekirdek ortada bir bezelye kadar kalırdı." },
  { id: "p11-258", k: "Bilim", s: "Bir elementin atom numarası neyi gösterir?", d: "Çekirdekteki proton sayısını", y: ["Nötron sayısını", "Atomun kütlesini"], a: "Proton sayısı elementin kimliğini belirler. Örneğin 6 protonlu her atom karbondur, 8 protonlu her atom oksijendir." },
  { id: "p11-259", k: "Bilim", s: "Proton sayısı aynı, nötron sayısı farklı atomlara ne denir?", d: "İzotop", y: ["İyon", "Molekül"], a: "İzotoplar aynı elementin farklı kütleli türleridir. Örneğin karbon-12 ve karbon-14 karbonun iki izotopudur." },
  { id: "p11-260", k: "Bilim", s: "Bir atomun kütle numarası neyin toplamıdır?", d: "Proton ve nötron sayısının", y: ["Proton ve elektron sayısının", "Yalnız nötron sayısının"], a: "Elektronlar çok hafif olduğu için kütle numarasına katılmaz. Örneğin karbon-14'te 6 proton ve 8 nötron vardır." },
  { id: "p11-261", k: "Bilim", s: "Elektronların çekirdek çevresinde yalnız belirli enerji düzeylerinde bulunabildiğini 1913'te öne süren kimdir?", d: "Niels Bohr", y: ["Ernest Rutherford", "Isaac Newton"], a: "Bohr modeli, hidrojen atomunun yaydığı ışığın neden belirli renklerde olduğunu açıkladı. Bohr 1922'de Nobel Fizik Ödülü'nü aldı." },
  { id: "p11-262", k: "Bilim", s: "Bir proton kaç kuarktan oluşur?", d: "3", y: ["2", "6"], a: "Proton iki yukarı ve bir aşağı kuarktan, nötron ise bir yukarı ve iki aşağı kuarktan oluşur." },
  { id: "p11-263", k: "Bilim", s: "Aşağıdakilerden hangisi bilinen bir iç yapısı olmayan temel parçacıktır?", d: "Elektron", y: ["Proton", "Nötron"], a: "Elektronun daha küçük parçalardan oluştuğuna dair hiçbir kanıt yoktur. Proton ve nötron ise kuarklardan oluşur." },
  { id: "p11-264", k: "Bilim", s: "Higgs bozonunun keşfi 2012'de hangi kurumun hızlandırıcısında duyuruldu?", d: "CERN", y: ["NASA", "Max Planck Enstitüsü"], a: "Higgs bozonu, Cenevre yakınındaki Büyük Hadron Çarpıştırıcısı'nda bulundu. Peter Higgs ve François Englert 2013'te Nobel Fizik Ödülü'nü aldı." },
  { id: "p11-265", k: "Bilim", s: "Atom çekirdeğindeki proton ve nötronları bir arada tutan kuvvet hangisidir?", d: "Güçlü nükleer kuvvet", y: ["Kütle çekimi", "Manyetik kuvvet"], a: "Protonlar birbirini elektriksel olarak iter. Çok kısa mesafede etkili olan güçlü nükleer kuvvet bu itmeyi yenerek çekirdeği bir arada tutar." },
  { id: "p11-266", k: "Bilim", s: "Aşağıdakilerden hangisi doğanın dört temel kuvvetinden biridir?", d: "Zayıf nükleer kuvvet", y: ["Sürtünme kuvveti", "Kaldırma kuvveti"], a: "Dört temel kuvvet kütle çekimi, elektromanyetik, güçlü nükleer ve zayıf nükleer kuvvettir. Sürtünme elektromanyetik etkileşimlerden doğar." },
  { id: "p11-267", k: "Bilim", s: "Dört temel kuvvetin en zayıfı hangisidir?", d: "Kütle çekimi", y: ["Elektromanyetik kuvvet", "Güçlü nükleer kuvvet"], a: "Küçük bir mıknatıs, bütün Dünya'nın çekimine rağmen bir ataşı yerden kaldırabilir. Kütle çekimi ancak çok büyük kütlelerde baskın hâle gelir." },
  { id: "p11-268", k: "Bilim", s: "Elektronun antimaddedeki karşılığı olan pozitif yüklü parçacığa ne denir?", d: "Pozitron", y: ["Proton", "Nötrino"], a: "Pozitronun kütlesi elektronla aynıdır ama yükü pozitiftir. 1932'de Carl Anderson tarafından kozmik ışınlarda bulundu." },
  { id: "p11-269", k: "Bilim", s: "Bir parçacık kendi antiparçacığıyla karşılaşırsa ne olur?", d: "Yok olup enerjiye dönüşürler", y: ["Birleşip ağır bir atom oluştururlar", "Hiçbir şey olmaz"], a: "Elektron ile pozitron karşılaşınca kütleleri E = mc² uyarınca enerjiye, genellikle gama ışınlarına dönüşür." },
  { id: "p11-270", k: "Bilim", s: "Antimaddenin varlığını 1928'deki denklemiyle ilk öngören fizikçi kimdir?", d: "Paul Dirac", y: ["Werner Heisenberg", "Enrico Fermi"], a: "Dirac'ın elektron denklemi, elektronla aynı kütlede ama zıt yüklü bir parçacığın varlığını gerektiriyordu. Bu parçacık birkaç yıl sonra bulundu." },
  { id: "p11-271", k: "Bilim", s: "Maddeyle neredeyse hiç etkileşmeden her saniye vücudumuzdan trilyonlarcası geçen parçacık hangisidir?", d: "Nötrino", y: ["Proton", "Alfa parçacığı"], a: "Güneş'teki füzyon tepkimeleri çok büyük sayıda nötrino üretir. Nötrinoların çoğu Dünya'nın içinden bile hiçbir şeye çarpmadan geçer." },
  { id: "p11-272", k: "Bilim", s: "Dünyanın en büyük parçacık hızlandırıcısı olan Büyük Hadron Çarpıştırıcısı'nın çevresi yaklaşık kaç km'dir?", d: "27 km", y: ["2,7 km", "270 km"], a: "CERN'deki tünel, İsviçre-Fransa sınırının altında yaklaşık 100 metre derinlikte ve 27 km çevresindedir." },
  { id: "p11-273", k: "Bilim", s: "Atom ve parçacık fiziğinde sık kullanılan \"elektronvolt\" neyin birimidir?", d: "Enerjinin", y: ["Akımın", "Uzaklığın"], a: "1 elektronvolt, bir elektronun 1 voltluk potansiyel farkında kazandığı enerjidir; yaklaşık 1,6 × 10⁻¹⁹ joule." },
  { id: "p11-274", k: "Bilim", s: "Yaygın hidrojen atomunun çekirdeğinde ne bulunur?", d: "Tek bir proton", y: ["Bir proton ve bir nötron", "İki elektron"], a: "Hidrojenin en yaygın izotopunda çekirdek yalnız bir protondur. Döteryumda buna bir nötron, trityumda iki nötron eklenir." },
  { id: "p11-275", k: "Bilim", s: "Radyoaktiviteyi 1896'da uranyum tuzlarıyla çalışırken keşfeden kimdir?", d: "Henri Becquerel", y: ["Wilhelm Röntgen", "Ernest Rutherford"], a: "Becquerel, uranyum tuzlarının karanlıkta bile fotoğraf plağını kararttığını fark etti. 1903 Nobel Fizik Ödülü'nü Curie çiftiyle paylaştı." },
  { id: "p11-276", k: "Bilim", s: "Polonyum ve radyum elementlerini 1898'de keşfeden kimlerdir?", d: "Marie ve Pierre Curie", y: ["Otto Hahn ve Lise Meitner", "Rutherford ve Soddy"], a: "Curie çifti tonlarca uranyum cevherini işleyerek bu iki yeni radyoaktif elementi ayırdı." },
  { id: "p11-277", k: "Bilim", s: "Polonyum elementi adını nereden alır?", d: "Marie Curie'nin doğduğu ülkeden", y: ["Bir Yunan tanrısından", "Kuzey Kutbu'ndan"], a: "Marie Curie Varşova'da doğdu. Keşfettiği elemente, o dönem bağımsız olmayan vatanı Polonya'nın adını verdi." },
  { id: "p11-278", k: "Bilim", s: "Marie Curie Nobel ödüllerini hangi iki alanda aldı?", d: "Fizik ve kimya", y: ["Fizik ve tıp", "Kimya ve barış"], a: "Curie 1903'te fizik, 1911'de kimya ödülünü aldı. İki farklı bilim dalında Nobel kazanan ilk kişidir." },
  { id: "p11-279", k: "Bilim", s: "Radyoaktif bir maddede \"yarı ömür\" ne demektir?", d: "Atomların yarısının bozunma süresi", y: ["Maddenin ömrünün tam yarısı", "Işımanın iki katına çıkma süresi"], a: "Her yarı ömür sonunda kalan radyoaktif atomların yarısı bozunur. Bu süre izotoptan izotopa saniyelerden milyarlarca yıla kadar değişir." },
  { id: "p11-280", k: "Bilim", s: "Radyoaktif bir örnekten 3 yarı ömür sonra başlangıçtakinin ne kadarı kalır?", d: "Sekizde biri", y: ["Üçte biri", "Altıda biri"], a: "Her yarı ömürde miktar yarıya iner: 1/2, 1/4, 1/8. Üç yarı ömür sonunda başlangıçtakinin sekizde biri kalır." },
  { id: "p11-281", k: "Bilim", s: "Arkeolojideki organik kalıntıların yaşı genellikle hangi izotopla belirlenir?", d: "Karbon-14", y: ["Uranyum-238", "Oksijen-16"], a: "Canlılar yaşarken karbon-14 alır, ölünce alım durur ve bu izotop bozunmaya başlar. Kalan miktar ölçülerek yaklaşık 50.000 yıla kadar tarihleme yapılabilir." },
  { id: "p11-282", k: "Bilim", s: "Karbon-14'ün yarı ömrü yaklaşık ne kadardır?", d: "5700 yıl", y: ["57 yıl", "5,7 milyon yıl"], a: "Karbon-14'ün yarı ömrü yaklaşık 5730 yıldır. Bu süre, binlerce yıllık kalıntıları tarihlemeye çok uygundur." },
  { id: "p11-283", k: "Bilim", s: "Alfa parçacığı neden oluşur?", d: "2 proton ve 2 nötrondan", y: ["Tek bir elektrondan", "Yüksek enerjili ışıktan"], a: "Alfa parçacığı bir helyum çekirdeğidir. Ağır ve yüklü olduğu için maddeye pek giremez." },
  { id: "p11-284", k: "Bilim", s: "Beta eksi bozunmasında çekirdekten hangi parçacık fırlar?", d: "Elektron", y: ["Proton", "Helyum çekirdeği"], a: "Beta eksi bozunmasında çekirdekteki bir nötron protona dönüşür, bu sırada bir elektron ve bir antinötrino yayılır." },
  { id: "p11-285", k: "Bilim", s: "Hangi radyoaktif ışınım tek bir kâğıt yaprağıyla durdurulabilir?", d: "Alfa", y: ["Gama", "Nötron"], a: "Alfa parçacıkları havada yalnız birkaç santimetre gidebilir. Beta için ince alüminyum, gama için kalın kurşun ya da beton gerekir." },
  { id: "p11-286", k: "Bilim", s: "Alfa, beta ve gama ışınımlarından hangisi maddeye en derin girer?", d: "Gama", y: ["Alfa", "Beta"], a: "Gama ışınımı yüksüz ve kütlesizdir, bu yüzden maddeyle seyrek etkileşir. Onu zayıflatmak için kalın kurşun ya da beton gerekir." },
  { id: "p11-287", k: "Bilim", s: "Radyoaktif ışınımı algılayıp çıtırtı sesiyle haber veren alete ne denir?", d: "Geiger sayacı", y: ["Sismograf", "Barometre"], a: "Geiger-Müller tüpünden geçen ışınım içerideki gazı iyonlaştırır ve kısa bir elektrik akımı oluşturur. Her sayım bir çıtırtı olarak duyulur." },
  { id: "p11-288", k: "Bilim", s: "Radyasyon dozunun insan sağlığına etkisi hangi birimle ifade edilir?", d: "Sievert", y: ["Pascal", "Weber"], a: "Sievert, alınan ışınım türünü ve dokunun duyarlılığını hesaba katar. Günlük ölçümlerde genelde milisievert kullanılır." },
  { id: "p11-289", k: "Bilim", s: "Saniyede bir radyoaktif bozunmaya karşılık gelen aktivite birimi hangisidir?", d: "Becquerel", y: ["Sievert", "Kandela"], a: "Birim, radyoaktiviteyi keşfeden Henri Becquerel'in adını taşır. Eski birim curie ise 37 milyar becquerele eşittir." },
  { id: "p11-290", k: "Bilim", s: "Nükleer santrallerde enerji hangi tepkimeyle üretilir?", d: "Fisyon (çekirdek bölünmesi)", y: ["Füzyon (çekirdek kaynaşması)", "Yanma"], a: "Uranyum gibi ağır çekirdekler nötronla bölünür ve büyük enerji açığa çıkar. Bu ısı suyu buhara çevirir, buhar türbini döndürür." },
  { id: "p11-291", k: "Bilim", s: "Nükleer santrallerde yakıt olarak en çok hangi izotop kullanılır?", d: "Uranyum-235", y: ["Karbon-14", "Hidrojen-1"], a: "Doğal uranyumun yalnız yaklaşık yüzde 0,7'si uranyum-235'tir. Çoğu reaktörde yakıt, bu oran yüzde 3-5'e çıkarılarak zenginleştirilir." },
  { id: "p11-292", k: "Bilim", s: "Güneş enerjisini temelde hangi tepkimeyle üretir?", d: "Hidrojenin helyuma kaynaşması", y: ["Uranyumun bölünmesi", "Kömürün yanması"], a: "Güneş'in merkezinde hidrojen çekirdekleri birleşerek helyum oluşturur. Bu nükleer füzyonda kütlenin küçük bir kısmı enerjiye dönüşür." },
  { id: "p11-293", k: "Bilim", s: "Otto Hahn'ın 1938 deneylerindeki uranyum bölünmesini fiziksel olarak ilk açıklayanlardan olan kadın fizikçi kimdir?", d: "Lise Meitner", y: ["Marie Curie", "Emmy Noether"], a: "Meitner, yeğeni Otto Frisch ile birlikte uranyum çekirdeğinin ikiye bölündüğünü açıkladı ve süreci fisyon olarak adlandırdı." },
  { id: "p11-294", k: "Bilim", s: "Fisyonda zincirleme tepkimeyi sürdüren parçacık hangisidir?", d: "Nötron", y: ["Elektron", "Foton"], a: "Bölünen her uranyum-235 çekirdeği ortalama 2-3 yeni nötron açığa çıkarır. Bu nötronlar başka çekirdekleri böler ve tepkime sürer." },
  { id: "p11-295", k: "Bilim", s: "İlk kontrollü nükleer zincirleme tepkimeyi 1942'de Chicago'da gerçekleştiren ekibin lideri kimdir?", d: "Enrico Fermi", y: ["Albert Einstein", "Niels Bohr"], a: "Fermi'nin ekibi Chicago Pile-1 adlı reaktörü bir stadyumun tribünleri altında kurdu. Tepkime 2 Aralık 1942'de başladı." },
  { id: "p11-296", k: "Bilim", s: "Pek çok ülkede insanların aldığı doğal radyasyonun en büyük kaynağı nedir?", d: "Radon gazı", y: ["Cep telefonları", "Mikrodalga fırınlar"], a: "Radon, topraktaki uranyumun bozunmasıyla oluşan radyoaktif bir gazdır. Kapalı ve iyi havalandırılmayan yerlerde birikebilir." },
  { id: "p11-297", k: "Bilim", s: "Muzların çok hafif radyoaktif olmasının nedeni nedir?", d: "İçerdikleri potasyum-40", y: ["Uranyum içermeleri", "Güneşten radyasyon emmeleri"], a: "Muz potasyum bakımından zengindir. Doğal potasyumun çok küçük bir kısmı radyoaktif potasyum-40'tır; doz zararsız düzeydedir." },
  { id: "p11-298", k: "Bilim", s: "Radyoaktif bir maddeyi ısıtmak yarı ömrünü pratikte nasıl etkiler?", d: "Etkilemez", y: ["Yarıya indirir", "İki katına çıkarır"], a: "Radyoaktif bozunma çekirdekte gerçekleşir. Sıradan ısıtma, basınç ya da kimyasal tepkimeler yarı ömrü pratikte değiştirmez." },
  { id: "p11-299", k: "Bilim", s: "Uranyum çekirdeğinde kaç proton bulunur?", d: "92", y: ["82", "238"], a: "Uranyumun atom numarası 92'dir. Uranyum-238'deki 238 sayısı ise proton ve nötronların toplamıdır." },
  { id: "p11-300", k: "Bilim", s: "Atom altı parçacıklardan hangisi elektrik yükü taşımaz?", d: "Nötron", y: ["Proton", "Elektron"], a: "Nötron yüksüzdür, adını da buradan alır. Yükü olmadığı için çekirdeğe kolayca yaklaşabilir; fisyonu başlatmada bu yüzden kullanılır." },
  { id: "p11-301", k: "Bilim", s: "Rutherford'un deneyinde altın levhaya gönderdiği parçacıklar hangileriydi?", d: "Alfa parçacıkları", y: ["Nötronlar", "Fotonlar"], a: "Deneyi Rutherford'un yönetiminde Geiger ve Marsden yaptı. Parçacıkların çoğu levhadan geçti, pek azı büyük açılarla saptı." },
];
